pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for anything
    // (below the minimum plausible item footprint) are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: heavy penalty, worse the closer it is to zero.
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving a gap that can't fit the lookahead item if this bin
    // would otherwise be a natural host for it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin is attractive early or when
    // no open bin fits well, but should be avoided when an open bin gives
    // a decent fit (post_residual small) to prevent bin explosion.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 25.0 * progress;
        // Cheaper to open a bin if existing bins are quite full on average.
        score -= 0.3 * (100.0 - mean_residual);
        // If the only alternative is a poor fit (large post_residual in others),
        // the empty-bin score above is competitive; if others fit tightly,
        // their -40*fill_ratio bonus will beat this.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight preference to open bins that can still host the next item.
            score -= 5.0;
        }
    }

    score
}

