        let mid = (progress - 0.35) / 0.4;
        let bell = (mid * (1.0 - mid) * 4.0).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr).abs() / mr;
        if dev <= 0.5 {
            score -= 6.0 * bell * (1.0 - dev / 0.5);
        } else {
            score += 4.0 * bell * (dev - 0.5).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    // Items are 1..100, so a residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for new bins early vs late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
