            let d = (after - mr).abs();
            if d <= 2.0 {
                score -= 12.0 * (1.0 - d / 2.0) * (0.6 + 0.9 * (1.0 - progress));
            }
        }
    }

    // gen 40: fresh-bin efficiency gate.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let harvestable = fresh_post >= mr * 1.1;
        if !harvestable {
            score += 10.0 * (1.0 - fresh_post / (mr * 1.1)) * (0.5 + 0.7 * progress);
        } else if fresh_post >= mr * 1.6 {
            score -= 7.0 * ((fresh_post / cap_f).min(0.4)) * (0.5 + 0.6 * (1.0 - progress));
        }
    }

    // gen 41: cumulative dead-space ledger.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let stranded_frac = 1.0 - pr / n;
        score += 6.0 * stranded_frac * stranded_frac * (0.8 + 1.0 * stream_left);
    }

    // gen 41: harvest-chain momentum.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after <= mr * 0.5 {
                score -= 8.0 * (1.0 - after / (mr * 0.5)) * (0.7 + 0.8 * progress);
            }
        }
    }

    // gen 41: fresh-bin threshold tightening.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(2.0) };
        if fresh_post < n * 0.6 {
            score += 15.0 * (1.0 - fresh_post / (n * 0.6)) * (0.6 + 0.6 * progress);
        }
    }

    // gen 42: multi-item capacity ledger.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).floor();
        let stream_left = 1.0 - progress;
        if k < 1.0 {
            score += 7.0 * (1.0 - pr / n) * (0.9 + 1.1 * stream_left);
        } else if k >= 2.0 {
            score -= 5.0 * (k.min(3.0) - 1.0) * (0.6 + 0.6 * (1.0 - progress));
        }
    }

    // gen 42: fresh-bin density veto.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        if fresh_post >= n {
            let excess = fresh_post - n;
            if excess > n && excess > mean_residual.max(2.0) {
                score += 8.0 * ((excess - n) / cap_f).min(0.3) * 10.0 * (0.5 + 0.7 * progress);
            }
        }
    }

    // gen 42: tight-closure sweep.
    if post_residual > 0 && post_residual <= 6 {
        let tail = (1.0 - progress).max(0.0);
        score -= (7.0 - post_residual as f64) * (1.2 + 1.3 * (1.0 - tail));
    }

    // gen 43 retained: perfect-fit ladder.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 1.0 && (pr - k * n).abs() < 0.5 {
            score -= 10.0 * (1.0 + 0.8 * (1.0 - progress)) / k.sqrt();
        }
    }

    // gen 43 retained: fresh-bin exact-closure gate.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let k = (fresh_post / n).round();
        if k < 1.0 || (fresh_post - k * n).abs() >= 2.0 {
            score += 9.0 * (1.0 - (fresh_post / (k.max(1.0) * n)).min(1.0)) * (0.5 + 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0) * (0.6 + 0.6 * progress);
        }
    }

    // gen 43 retained: late-stream residual compression.
    if progress > 0.8 && post_residual > 0 {
        let tail = (progress - 0.8) / 0.2;
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 5.0 * tail * (1.0 - pr / mr);
        } else {
            score += 4.0 * tail * ((pr - mr) / cap_f).min(0.2) * 10.0;
        }
    }

    // gen 44 retained: harvest-depth ladder.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let after = pr - n;
        let chain_k = (after / mr).floor();
        if chain_k >= 1.0 {
            let slack = after - chain_k * mr;
            let centered = 1.0 - (slack / mr).abs();
            score -= 11.0 * centered * (chain_k.min(3.0).sqrt()) * (0.7 + 0.9 * (1.0 - progress));
        }
    }

    // gen 44 retained: fresh-bin chain-capacity gate.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let fresh_chain = if fresh_post >= n { ((fresh_post - n) / mr).floor() } else { -1.0 };
        let alt_chain = 1.0;
        if fresh_chain < alt_chain {
            let deficit = (alt_chain - fresh_chain.max(0.0)) / alt_chain;
            score += 12.0 * deficit * (0.4 + 0.6 * (fitting_bins_count as f64).min(3.0) / 3.0) * (0.5 + 0.7 * progress);
        } else if fresh_chain >= 2.0 && progress < 0.6 {
            score -= 6.0 * (fresh_chain.min(3.0) - 1.0) * (1.0 - progress);
        }
    }

    // gen 44 retained: mid-stream residual smoothing.
    if progress > 0.35 && progress < 0.75 && post_residual > 10 && post_residual < 40 {
        let mid = (progress - 0.35) / 0.4;
        let bell = (mid * (1.0 - mid) * 4.0).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr).abs() / mr;
        if dev <= 0.5 {
            score -= 6.0 * bell * (1.0 - dev / 0.5);
        } else {
            score += 4.0 * bell * (dev - 0.5).min(1.0);
        }
    }

    // gen 45 retained: chain-terminal sweep.
    if post_residual > 0 && post_residual <= 12 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round().max(1.0);
        let dev = (pr - k * mr).abs();
        if dev <= 1.0 {
            score -= 9.0 * (1.0 - dev) * (0.6 + 0.8 * (1.0 - progress));
        } else if dev >= 3.0 && pr < mr {
            score += 5.0 * ((dev - 3.0) / mr).min(1.0) * (0.5 + 0.7 * (1.0 - progress));
        }
    }

    // gen 45 retained: fragmentation-avoidance gate on fresh bins.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 && progress > 0.15 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post < mr * 0.55 {
            let stranded = 1.0 - fresh_post / (mr * 0.55);
            score += 13.0 * stranded * (0.4 + 0.9 * (1.0 - progress));
        }
    }

    // gen 45 retained: competition-weighted exact-closure bonus.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 7.0 * ((fitting_bins_count as f64).ln() + 1.0).min(3.0) * (0.6 + 0.6 * (1.0 - progress));
    }

    // gen 46 retained: dead-space liquidity ranking.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.5 {
            score += 11.0 * (0.5 - liquidity) * (0.5 + 1.3 * stream_left);
        } else if liquidity <= 1.5 {
            let center = 1.0 - (liquidity - 1.0).abs() / 0.5;
            score -= 8.0 * center.max(0.0) * (0.4 + 0.9 * stream_left);
        }
    }

    // gen 46 retained: fresh-bin two-item packing guarantee.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post >= n {
            let after2 = fresh_post - n;
            if after2 >= mr {
                score -= 10.0 * ((after2 - mr) / cap_f).min(0.2) * 5.0 * (0.5 + 0.7 * (1.0 - progress));
            } else {
                score += 9.0 * (1.0 - after2 / mr) * (0.5 + 0.8 * progress);
            }
        }
    }

    // gen 46 retained: sliver-elimination sharpening.
    if post_residual > 0 && post_residual <= 4 {
        let pr = post_residual as f64;
        score -= 10.0 * (5.0 - pr) * (0.5 + 0.9 * progress);
    } else if post_residual > 4 && post_residual <= 9 && fitting_bins_count > 1 {
        score += 4.0 * (1.0 - (post_residual as f64 - 4.0) / 5.0) * (0.4 + 0.6 * progress);
    }

    // gen 47 retained: liquidity band refinement.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.4 {
            let dead = (0.4 - liquidity) / 0.4;
            score += 6.0 * dead * dead * (0.6 + 1.4 * stream_left);
        } else if liquidity <= 2.0 {
            let center = (1.0 - (liquidity - 1.0).abs() / 1.0).max(0.0);
            score -= 7.0 * center * (0.5 + 0.7 * stream_left);
        }
    }

    // gen 47 retained: harvest-continuity guard.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = (after / mr).round().max(1.0);
        let dev = (after - k * mr).abs() / mr;
        if dev <= 0.15 {
            score -= 6.0 * (1.0 - dev / 0.15) * (0.4 + 0.9 * progress) / k.sqrt();
        }
    }

    // gen 47 retained: fresh-bin chain-depth discount.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let slack_after_next = fresh_post - n;
        if slack_after_next < mr * 0.5 {
            let deficit = 1.0 - (slack_after_next / (mr * 0.5)).max(0.0);
            score += 8.0 * deficit * (0.5 + 1.0 * stream_left);
        } else if slack_after_next >= mr * 1.5 && stream_left > 0.2 {
            score -= 5.0 * ((slack_after_next - mr * 1.5) / cap_f).min(0.2) * 5.0 * stream_left;
        }
    }

    // MUTATION (gen 48): dead-space deficit ledger — for open bins whose
    // post-residual cannot hold the next item, penalize proportionally to the
    // squared shortfall normalized by the mean residual, with weight ramping
    // up in the final third of the stream where stranded slivers become
    // unrecoverable. Complements the liquidity band by attacking the exact
    // bins that create the dead-space ratio the diagnosis flagged.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let shortfall = (n - pr) / mr;
        let late = ((progress - 0.65) / 0.35).clamp(0.0, 1.0);
        score += 5.0 * shortfall * shortfall * (0.5 + 1.5 * late);
    }

    // MUTATION (gen 48): harvest-margin floor — when the post-residual holds
    // the next item, reward placements that leave a leftover still above the
    // smallest plausible item (mean residual * 0.35), ensuring chains remain
    // terminable; scale the reward by remaining stream so early placements
    // preserve future flexibility more aggressively.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        if after < mr * 0.35 {
            score += 7.0 * (1.0 - after / (mr * 0.35)) * (0.4 + 1.2 * stream_left);
        }
    }

    // MUTATION (gen 48): fresh-bin opening threshold — only allow a new bin
    // when its post-residual exceeds the mean residual demand by a margin
    // that shrinks with progress; late-stream fresh bins must be strictly
    // more liquid than average to justify the extra bin count.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let margin_needed = mr * (1.6 - 0.8 * progress);
        if fresh_post < margin_needed {
            let deficit = 1.0 - fresh_post / margin_needed;
            score += 9.0 * deficit * (0.5 + 0.8 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // retained mutations.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
