pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (small leftovers that few future items can fill) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Dead space relative to the smallest item size (1 in general interface):
    // penalize residuals that cannot hold the lookahead item if it would fit snugly.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // leftover too small for the next item
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // leaves room for the lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins,
    // favor filling existing bins as open_bins_count grows.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make opening a fresh bin costly unless the item is large
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 1.5 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 10.0; // large items start fresh bins more willingly
        }
    }

    // Mean-residual coupling: if mean residual is high, prefer bins that
    // reduce dispersion (fill down toward the mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Late-stream urgency: as the stream progresses, avoid leaving many
    // half-empty bins; tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 8.0 * (1.0 - tightness.min(1.0));

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally to waste
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.3 * unusable;
        }
    } else {
        // Last item: strongly prefer minimal residual
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: bins with residual already below mean
    // are "almost closed"; encourage filling them.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive if nothing fits well anywhere
    if bin_residual == bin_capacity {
        // base penalty so open bins win when reasonably tight
        score += 20.0;
        // but if many bins are open and mean residual is large (fragmented),
        // opening fresh space can be better late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 15.0 * progress;
        }
        // new bin leaves full 100 residual; if next item is huge it's fine
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Penalize leaving tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Core best-fit shaping: reward tight fits non-linearly ---
    let fit_ratio = post_residual as f64 / bin_capacity as f64; // 0 = perfect fit
    score += 12.0 * fit_ratio * fit_ratio; // penalize large leftover space quadratically

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Lookahead coupling with next item ---
    if next_item_size > 0 {
        // If the next item fits exactly in the post residual, strongly favor this bin
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more waste -> mild reward proportional to fit tightness
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // next item will NOT fit here: leftover space is likely dead unless reusable later.
            // Penalize moderately, but less if residual is large enough to be useful for typical items.
            let dead = post_residual as f64;
            let useful_threshold = 20.0; // residuals >= 20 can host small items
            if dead < useful_threshold {
                score += 18.0 * (useful_threshold - dead) / useful_threshold;
            } else {
                score += 3.0; // mild penalty, residual still reusable
            }
        }
    } else {
        // Last item: just minimize waste, prefer any bin over opening a new one
        score -= 100.0;
    }

    // --- Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- Global state coupling: mean residual vs this bin's residual ---
    // Prefer bins whose residual is below the mean (tighter bins get filled first),
    // keeping large-residual bins flexible for bigger future items.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // --- Time horizon adaptation ---
    // Early in the stream: be conservative, keep bins balanced (avoid extreme fragmentation).
    // Late in the stream: pack greedily, minimize bins at all costs.
    let early_bias = (1.0 - progress) * 8.0;
    let late_bias = progress * 10.0;

    // Early: penalize bins that would end up with awkward mid-range residuals
    if post_residual > 0 && post_residual < 10 {
        score += early_bias; // tiny residuals are dead weight, worse early on
    }
    // Late: reward using almost-full bins aggressively
    if bin_residual as f64 <= mean_residual {
        score -= late_bias;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when: many open bins already fragmented,
        // item is large, and no tight fit exists. Base cost keeps it a last resort.
        score = 55.0
            + item_size as f64 * 0.1
            - (fitting_bins_count as f64) * 0.0; // neutral base
        // If item is large and would leave a very small residual in any open bin,
        // a fresh bin keeps large residual intact for future large items.
        if item_size >= 60 && open_bins_count > 3 {
            score -= 20.0;
        }
        // Late in stream: opening new bins is expensive (likely not filled again)
        score += progress * 30.0;
        // If only one bin fits and it's a decent fit, strongly prefer existing bin
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // --- Open bins count pressure: with many open bins, consolidate ---
    if open_bins_count > 5 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // early on, tolerate waste; late, punish residual waste quadratically.
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score += 30.0 * norm_pr * norm_pr * progress_poly;

    // Reward near-perfect fits with a smooth cubic bonus.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / cap;
        score -= 15.0 * fit_frac * (1.0 - fit_frac) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize leaving residual that nothing upcoming can use, scaled by progress.
        score += 10.0 * norm_pr * (0.3 + progress);
    }

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize opening bins early, allow late.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score = cap * (1.2 - 0.6 * progress) - 10.0 * openness;
    }

    // Slight pull toward bins with residual close to mean (smooth dispersion term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // usable bands. Residuals that are 0 (perfect fit) are heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0; // near-perfect: dead space is negligible
    } else if post_residual <= 25 {
        score -= 15.0; // still useful for small items
    } else if post_residual <= 50 {
        score += 10.0; // mid leftover: moderately wasteful
    } else {
        score += 30.0; // large leftover: big dead space risk
    }

    // Integer-division thresholds: does the leftover admit a "typical"
    // follow-up item (<= 25, <= 50)? Reward leftovers that can host
    // a whole harmonic class of future items.
    let hosts_small = post_residual / 25;   // 0..=4
    let hosts_mid   = post_residual / 50;   // 0..=2
    score -= 8.0 * hosts_small as f64;
    score -= 4.0 * hosts_mid as f64;

    // Lookahead coupling: if the next item fits exactly or well into the
    // post residual, strongly favor this bin (2-chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Modulo arithmetic on residual: prefer leftovers aligned to common
    // size classes (multiples of 10 and 20), which recur in many streams.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity / 2 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (poor fits are penalized
    // above) or when the current item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.5 + 20.0;
        // Prefer fresh bins early in the stream and for big items.
        score -= 15.0 * (1.0 - progress);
        score -= 0.3 * item_size as f64;
        // If many bins already fit the item, opening a new one is wasteful.
        score += 10.0 * fitting_bins_count as f64;
        // If mean residual is large and could host the item, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        // Lookahead: a fresh bin can absorb both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> tighter packing.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize unusable gaps: gap too small to hold even the smallest item (1..=10)
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0; // hard penalty for tiny dead space
        } else {
            // Mild penalty scaled by how little the gap can still be used
            let usable = dead / bin_capacity as f64;
            score += 8.0 * (1.0 - usable);
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the gap is used by the next item
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * use_ratio;
        } else {
            // Next item cannot use this gap: penalize if gap is small/dead
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins when unnecessary.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: if this bin's residual is far below mean (already tight),
    // filling it further is good; if residual is much larger than mean, penalize slightly.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid).min(50.0);
    } else {
        score += 0.3 * (resid - mean_residual).min(50.0);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64 * progress;
        // But if the item is large and would leave a well-structured residual, soften.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Prefer tight fits overall: reward small post_residual relative to item size.
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward residuals that match the next item exactly ---
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for next item is extremely desirable
        score -= 60.0 * (1.0 - match_gap / 100.0).max(0.0).powi(4);
        // Penalize residuals that can't host the next item at all (dead space)
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        }
        // Bonus if this placement leaves room for next item AND current fit is tight
        if post_residual >= next_item_size && item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // --- Tightness reward: minimize leftover relative to capacity ---
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // --- Relative residual vs mean: prefer bins already below-average residual
    // (concentrate waste into few bins) ---
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // --- Last-chance bin: strongly favor using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling: only open a new bin when no open bin is decent ---
    if bin_residual == bin_capacity {
        // Base new-bin cost
        score = bin_capacity as f64 * 0.55;
        // Opening early in the stream or when few bins are open is cheaper
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // If the next item is large and this item is large, a fresh bin is fine
        if item_size >= 60 && next_item_size >= 50 {
            score -= 15.0;
        }
        // If existing bins fit well (low post_residual exists elsewhere), opening is bad;
        // approximate via fitting_bins_count: many fitting bins => don't open new
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // --- Late-stream consolidation: prefer filling existing bins as stream ends ---
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best (base score already does this),
    // but add a superlinear penalty for large leftover space to fight fragmentation.
    let frac_waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac_waste * frac_waste;

    // If the next item would fit in the post-residual, reward this bin strongly:
    // chaining two items into one bin is highly desirable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.5 * (next_item_size as f64);
        } else {
            // Penalize leaving a residual too small for the next item (dead space trap),
            // scaled by how close the wasted gap is.
            let gap = (post_residual as f64).max(0.0);
            if gap > 0.0 {
                score += 6.0 * (gap / bin_capacity as f64);
            }
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is already small relative to the mean:
    // consolidate into the most-filled bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage closing them out (prefer low-residual bins more).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += pressure * frac_waste * 10.0;

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it moderately attractive only when the item is large and would leave
    // a big awkward residual in any existing bin, or when few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin; decreases as stream progresses and
        // as the item gets bigger.
        score += 20.0 * (1.0 - large_item);
        if fitting_bins_count > 1 {
            score += 10.0; // discourage opening when alternatives exist
        }
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If next item is huge, a fresh bin with room for it is valuable.
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Mild time-dependent tightening: later in the stream, be stricter about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * frac_waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear penalty for mid-range waste
    let mut score = x * (1.0 + 2.0 * x * (1.0 - x)) * cap;

    // Smooth interaction with stream progress: later in stream, waste matters more
    score += 20.0 * x * x * progress;

    // Reward tight fits (small post_residual) with smooth inverse coupling
    score -= 15.0 * (1.0 - x).powi(3);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).max(0.0);
        score -= 12.0 * (1.0 - fit_gap).powi(2) * (1.0 - progress * 0.5);
        // Penalize if next item cannot use the leftover
        score += 6.0 * x * (nx / (x + 0.01)).min(1.0) * (nx > x) as i32 as f64;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // New-bin candidate: neutral baseline, penalized relative to good fits
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress);
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Mild penalty for too many open bins relative to waste
    score += 0.5 * open_bins_count as f64 * x * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // multiples of common size classes (e.g. 25, 50, 20, 10).
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual % 25 == 0 {
        score -= 25.0;
    } else if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        score += 30.0; // dead space below smallest item size
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 25 == 0 || next_post == 0 {
                score -= 12.0;
            } else if next_post < 10 {
                score += 10.0; // next placement would create dead space
            }
        } else {
            // next item cannot fit here; residual must serve future items
            score += 5.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins
    // unless the fit is terrible (post_residual large means bad fit anyway).
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for fragmenting across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    // Items are 1..100, so a residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for new bins early vs late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fits (item + next item fill residual).
    if next_item_size > 0 {
        let chain = item_size as f64 + next_item_size as f64;
        let residual = bin_residual as f64;
        if chain <= residual {
            // Both current item AND the next item fit in this bin: strong reward.
            score -= 40.0 + (residual - chain); // extra reward for tighter chains
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item exactly fills post_residual: near-perfect pairing.
            score -= 25.0;
        } else {
            // Dead space created relative to next item: penalize unusable leftover.
            let waste = post_residual as f64 - next_item_size as f64;
            if waste > 0.0 {
                score += waste.min(30.0);
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Penalize bins whose residual deviates above the mean (fragmented bins),
    // reward bins tighter than average (concentrating packing).
    if mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: base cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer compact bins: small post_residual is good; amplify non-linearity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Slight penalty for spreading across too many bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize bins far below mean residual (avoid fragmenting many half-full bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer filling bins when many bins are open (consolidation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Time horizon: later in the stream, be more conservative about opening new bins;
    // early on, allow exploration of new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early, expensive late.
        score += 120.0 * progress + 30.0;
        // But if nothing fits well anywhere (large dead space avoided), new bin is fine.
        if post_residual == 0 {
            score -= 500.0;
        }
        // If next item is large and current residual barely fits item, prefer new bin.
        if next_item_size > 0 && bin_residual - item_size < next_item_size {
            score -= 40.0;
        }
    }

    // Reward using residual that would otherwise be dead space (large item into large gap).
    if item_size > bin_capacity / 2 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and post-residual ratio
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_ratio = post_residual as f64 / cap;

    // Smooth non-linear coupling: quadratic waste penalty that grows with progress
    score += 3.0 * post_ratio * post_ratio * (0.5 + progress);

    // Cubic term: dead space becomes increasingly costly late in the stream
    score += 2.0 * post_ratio.powi(3) * (1.0 + 2.0 * progress);

    // Reward tight fits via smooth saturating interaction of item size and residual
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_quality * (1.0 - post_ratio) * (0.5 + progress);

    // Last-chance bin: smooth sigmoid-like reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - post_ratio) * (0.5 + progress);
    }

    // Lookahead: smooth reward if next item can exploit the post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let lookahead_util = next_item_size as f64 / cap;
        score -= 3.0 * lookahead_util * (1.0 - post_ratio + post_ratio * progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the lookahead item
        let waste = (next_item_size as f64 - post_residual as f64) / cap;
        score += 2.0 * waste * waste * (1.0 + progress);
    }

    // Smooth mean-residual coupling: prefer bins deviating from mean via tanh-like term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev.tanh() * (0.5 + progress);

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // granularities (5,10,20) remain reusable; odd/prime-ish residuals are dead space.
    let r = post_residual;
    let harmonic_bonus: f64 = if r == 0 {
        -60.0 // perfect fit: ideal
    } else if r % 20 == 0 {
        -18.0
    } else if r % 10 == 0 {
        -12.0
    } else if r % 5 == 0 {
        -6.0
    } else if r % 2 == 0 {
        0.0
    } else {
        6.0 // odd residual: awkward
    };
    score += harmonic_bonus;

    // Penalize small unusable dead space (below typical minimum item size band).
    if r > 0 && r < 10 {
        score += 25.0 + (10 - r) as f64 * 3.0;
    }

    // Lookahead: reward if next item exactly or loosely fits the new residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // exact chained fit
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 12.0 - slack * 0.15; // tighter future fit is better
        } else {
            score += 4.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it slightly unattractive unless current bins are
    // nearly full on average (consolidation phase early, fresh bins late).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 8.0 + 25.0 * (1.0 - progress) + mean_residual * 0.3;
        score += penalty;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees a home for the lookahead
        }
    }

    // Mild preference for filling fuller bins (relative fill ratio).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Crowd control: with many open bins, favor consolidation onto existing bins.
    if open_bins_count > 4 {
        score += 1.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    // A gap is "unusable" if it is smaller than the smallest plausible item (<=10)
    // or smaller than the lookahead item that could otherwise use it.
    if post_residual < 10 {
        score += 60.0; // total dead space: nothing can ever fill it
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // gap too small for the known next item
    } else if post_residual <= 15 {
        score += 8.0; // nearly-full bin: good, but keep ordering tight
    }

    // Reward very tight fits strongly (post_residual near zero but usable).
    if post_residual > 0 && post_residual <= 20 {
        score -= 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let open_pressure = (open_bins_count as f64 / 20.0).min(1.5);
    score += open_pressure * 6.0 * (mean_residual / bin_capacity as f64 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate handling: empty bin should only win when the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // penalize opening a new bin progressively with stream progress
        score += 45.0 + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // new bin can host the current + next item pair nicely
        }
    }

    // Lookahead synergy: reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward near-perfect fills nonlinearly
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping this bin viable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit in post-residual, penalize leaving awkward dead space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64 * (1.0 + progress);
    }

    // Penalize bins with residuals far from the mean residual (avoid fragmenting outliers)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let escape_penalty = if fitting_bins_count == 0 {
            -25.0 // nothing fits anywhere, opening a bin is necessary
        } else if fitting_bins_count == 1 {
            60.0 // a last-chance bin exists; strongly prefer it
        } else {
            25.0 + 20.0 * (1.0 - progress) // early on, consolidate into open bins
        };
        score += escape_penalty;
    }

    // Mild pressure to close out nearly-full bins late in the stream
    if post_residual < 10 {
        score -= 5.0 * (1.0 + progress);
    }

    // Slight preference for bins with larger residuals when many bins are open (balance load)
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * bin_residual as f64 * 0.01;

