}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late in the stream penalize them strongly.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * norm_post * norm_post * (1.0 + 2.0 * progress_poly);

    // Reward tight fits: cubic decay of penalty as post_residual shrinks.
    score -= 30.0 * (1.0 - norm_post).powi(3);

    // Lookahead coupling: penalize if next item fits poorly in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fits: reward proportional to how well it fills post residual
            let fill = nxt / post.max(1.0);
            score -= 15.0 * fill * (1.0 - progress_poly);
        } else {
            // next item won't fit here: penalize wasted residual
            score += 10.0 * norm_post * (0.5 + 0.5 * progress_poly);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress_poly + 0.5);
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin population balanced), scaled smoothly.
    let dev = (post - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // New-bin candidate: only attractive when residual of this bin is large
    // (i.e., item would leave a huge dead space elsewhere) — discourage early.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 * (1.0 - progress_poly) + 20.0 * norm_post;
        score += new_bin_penalty;
        // but if item is large relative to capacity, opening fresh is fine
        score -= 30.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
