    // Harmonic class of post_residual: residual modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    match class {
        0 => score -= 60.0,             // tiny dead space: excellent
        1 => score -= 15.0,             // small residual: still usable by small items
        2 => score += 5.0,              // mid residual: awkward
        3 => score += 25.0,             // large residual: wasteful placement
        _ => score += 40.0,             // item barely moved in: bad
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 300.0;
        } else if gap <= quarter {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement: penalize if this was avoidable.
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when the item
    // is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Reward new bin for large items, penalize for small ones.
        score = 250.0 - 200.0 * tightness + 50.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 60.0; // room for lookahead pairing
        }
        // Few open bins: mild preference to consolidate instead of spreading.
        score += 5.0 * open_bins_count as f64;
        return score;
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight consolidation pressure when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Dead-space penalty: residual that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // nearly exact, fine
    } else if post_residual >= 90 {
        score += 15.0; // item almost certainly belongs elsewhere
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
