            score -= 25.0 * (1.0 - progress);
        }
        // MUTATION: fresh-bin waste audit — opening a bin for a small item
        // strands most of the fresh capacity; penalize proportionally to
        // how little of the new bin the item consumes.
        let fill_frac = item_size as f64 / cap_f;
        if fill_frac < 0.5 {
            score += 45.0 * (0.5 - fill_frac) * (0.5 + progress);
        }
