    // MUTATION: dual-window chain bonus — when the post residual can host
    // both the next item and a plausible follow-up item drawn from the
    // residual distribution (proxied by mean residual), grant a compounding
    // reward that strengthens early when there is more stream left to pack.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
