    // dead-space ratio rather than only absolute residual size.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let unit = mean_residual.max(6.0).min(cap_f / 2.0);
        let hosts = pr / unit;
        if hosts < 1.0 {
            // Post-residual cannot hold even a typical item: escalating waste.
            score += 30.0 * (1.0 - hosts) * (0.6 + progress);
        } else if hosts < 2.0 {
            // Marginal hosting zone: small penalty to prefer better options.
            score += 8.0 * (2.0 - hosts) * (1.0 - progress);
        } else if hosts >= 3.0 {
            // Flexible residual: keep it alive as a staging bin.
            score -= 10.0 * ((hosts - 3.0) / 4.0).min(1.0) * (1.0 - progress);
