    }

    // MUTATION: pairing-value lookahead — when the next item would leave a
    // residual that exactly matches the current mean residual (a likely
    // upcoming size), grant a strong bonus for creating that chainable gap.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        let target = mean_residual.max(3.0) as u32;
        if after == target {
            score -= 35.0 * (1.0 - progress);
        } else if after > 0 && after < target {
            score += 10.0 * (1.0 - after as f64 / target as f64);
        }
    }

    score
}

