            score -= 25.0 * (1.0 - progress);
        }
    }

    // MUTATION: tight-fit precision band — residuals within 3 of the item
    // size (i.e., almost exact fit) get an extra escalating reward.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 9): residual-shape curvature — dead space whose size
    // matches common item magnitudes (multiples of a typical small item
    // footprint) is reusable; odd-sized gaps are penalized. This refines
    // the diagnosed dead-space weakness by valuing *usable* residuals,
    // not merely small ones.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let typical = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(2.0) };
        let k = (pr / typical).floor();
        let rem = pr - k * typical;
