    // 0.35 cutoff is replaced by a stream-aware cutoff that tightens late
    // in the stream, pushing consolidation when bins are nearly settled.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
