        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dual-window chain bonus — post residual can host next item plus a
    // plausible follow-up item proxied by mean residual.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    // New-bin gate tightening — fresh bin must beat near-perfect open fits,
    // scaled by remaining stream.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // MUTATION: refuse a fresh bin when some open bin leaves the next
        // item an exact landing spot — that chain is worth more than a new bin.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score += 55.0 * (1.0 - progress);
        }
    }

    // Tight-fit precision band — residuals within 3 of the item size get an
    // escalating reward.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION: residual reusability score — estimate how many typical items
    // (mean-residual sized) still fit in the post residual; each additional
    // reusable slot compounds the compaction reward.
    if post_residual > 0 {
        let typical = mean_residual.max(1.0);
        let slots = (post_residual as f64 / typical).floor();
        if slots >= 1.0 {
            score -= 12.0 * slots.min(3.0) * (0.6 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION: exact two-chain forecast — if placing here lets the next item
    // close a bin completely (post_residual == next_item_size already covered),
    // also reward the near-miss band where a small follow-up closes it.
    if post_residual > 0 && next_item_size > 0 {
        let after_next = post_residual as f64 - next_item_size as f64;
        if after_next > 0.0 && after_next <= mean_residual.max(4.0) {
            score -= 10.0 * (1.0 - after_next / mean_residual.max(4.0)) * (0.7 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that no typical item (>=1) can fill usefully:
    // small post residual is fine, but residual that is tiny relative to lookahead is bad.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; discourage unless current fits are poor.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score += 60.0 - 20.0 * progress + 25.0 * poor_fits;
        // Encourage opening a new bin when open bins are fragmented (high mean residual spread).
        if mean_residual > 0.0 && mean_residual < 20.0 {
            score -= 15.0;
        }
    } else {
        // Mildly reward using bins that are already partly filled when many bins are open.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill_ratio;
    }

    // Time horizon: later in the stream, prefer consolidating (avoid many open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Global fragmentation pressure: if mean residual is high, prefer bins above it
    // (drain the emptier bins first).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

