    // Dual-window chain bonus — residual can host next item plus a plausible
    // follow-up item (proxied by mean residual), compounding early.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
