    }

    // MUTATION: pair-fill anticipation — if the next item exactly fills the
    // post residual, reward strongly early in the stream.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // MUTATION: capacity-halving conservation — keep small items out of
    // half-empty bins early so large items retain room.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth interaction: residual waste penalized more as stream progresses
    let urgency = progress * progress;
    score += 12.0 * urgency * pr_norm * pr_norm;

    // Dead-space term: tiny residuals are nearly unusable; penalize smoothly
    let dead = (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 6.0 * dead * dead * pr_norm;

    // Lookahead coupling: reward residuals that can still hold next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 4.0 * snug * (1.0 - urgency);
        } else {
            score += 3.0 * (nx - pr) / cap * (0.5 + urgency);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - urgency);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidating
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * urgency;

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        score += 5.0 - 6.0 * fit_quality * (1.0 - urgency);
        score += 2.0 * urgency;
    }

    // Mean-residual alignment: prefer bins near mean residual for smooth packing
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 - urgency);

    score
}

