    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 group dead space
    // into capacity-fraction classes. Small post_residual in a "good" residue
    // class (near 0) is a tight fit; reward it.
    let post_class = post_residual % 10;
    let post_decile = (post_residual * 10) / bin_capacity; // 0..10 capacity fraction

    // Reward exact tight fits heavily (post_residual in lowest classes).
