    // Reward post_residual divisible by 10 (clean harmonic slot) and especially
    // divisible by 25 (quarter-capacity slots, reusable by many item sizes).
    if post_class == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, this is
    // a perfect pair placement -- big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves its own residue: prefer residues that
        // match harmonic classes of typical sizes (multiples of 5/10).
        let nxt_left = post_residual - next_item_size;
        if nxt_left % 10 == 0 {
            score -= 10.0;
        }
        score -= (nxt_left < 10) as i32 as f64 * 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for the next item -> dead space risk.
        // Penalize small-but-nonzero leftovers, scaled by fraction class.
        if post_residual < 10 {
            score += 15.0;
        } else if post_decile <= 3 {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; encourage it early in the
    // stream or when mean residual across open bins is already high (open
    // bins are all nearly full / fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + mean_residual * 0.3 - progress * 5.0
            + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 1 {
            score += 18.0; // discourage abandoning the sole fitting bin
        }
    }

    // Slight preference for bins whose residual is an integer-division
    // multiple of the item size (item tiles the space harmonically).
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 7.0;
    }

    score
}

