    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit bonus relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a decent fit; penalize it more as open_bins_count grows and
    // when the current bin residual is large.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
