    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION: residual utility ratio — sharpened threshold (0.4) so that
    // only genuinely reusable residual space is rewarded; sub-half-mean
    // leftovers are more likely dead space, penalized proportionally.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.4 {
            score += 14.0 * (1.0 - pr / (mr * 0.4)) * (1.0 - 0.5 * progress);
