            score -= 6.0 * ((pr - mr * 1.5) / cap_f).min(0.1) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION: perfect-pair lookahead — escalated late-stream, widened
    // near-exact band to within 3 with a graded reward.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
