            let usable_floor = (cap_f * 0.25).max(mean_residual.max(4.0));
            if after >= usable_floor {
                score -= 10.0 * (1.0 - progress) * (after / cap_f).min(0.3);
            } else if after < 8.0 {
                score += 9.0 * (1.0 - after / 8.0) * (0.7 + 0.5 * progress);
            }
        }
        // Double-host: residual fits the next item twice — extremely
        // valuable for streams with repeated medium sizes.
        if pr >= 2.0 * n && 2.0 * n <= cap_f {
            score -= 12.0 * (1.0 - 0.6 * progress);
        }
    }

    // MUTATION: waste-floor escalation — dead space measured against the
    // smallest plausible future demand (next item, or half the mean residual)
    // gets a quadratic penalty, sharpening the parent's linear dead-space
    // gradient which was diagnosed as the main weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let floor = if next_item_size > 0 {
            (next_item_size as f64).min(mean_residual.max(1.0) * 0.75)
        } else {
            mean_residual.max(1.0) * 0.75
        };
        if pr < floor {
            let deficit = 1.0 - pr / floor;
            score += 22.0 * deficit * deficit * (0.8 + 0.6 * progress);
        }
    }

    // MUTATION: fresh-bin parity check — a new bin is only justified when
    // its post-residual exceeds the best achievable post-residual among open
    // bins (proxied by mean residual minus the item); otherwise consolidate.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = (bin_capacity - item_size) as f64;
        let open_best_post = (mean_residual - item_size as f64).max(0.0);
        if fresh_post > open_best_post + cap_f * 0.15 {
            score -= 12.0 * (1.0 - progress);
        } else if fresh_post < open_best_post {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize bins far below mean residual (avoid fragmenting many half-full bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Consolidation pressure grows with open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Dead-space hazard: residual gaps too small for typical future items are
    // the main source of wasted bins. Sharper gradient toward zero.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.4 * (0.6 + progress);
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0 * progress;
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // When several bins can fit the item, prefer the emptiest reasonable bin.
    if fitting_bins_count > 2 {
        score += 0.35 * (bin_residual as f64 / cap_f) * 20.0;
    }

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size {
            score -= 55.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        // Fresh-bin pair-fit chain — open a fresh bin when the
        // item + next pair fits cleanly, giving the next item an exact fit.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
        // MUTATION: fresh-bin waste guard — only let a fresh bin win when the
        // leftover capacity of a fresh placement would be genuinely wasted;
        // penalize opening a bin when the fresh post-residual could still
        // hold the next item (usable space, so reuse an open bin instead).
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                score += 16.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
            }
        }
        // Late-stream reuse pressure: as the stream ends, closing out open
        // bins matters more than starting new ones.
        if fitting_bins_count > 1 {
            score += 30.0 * progress;
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space, sharper near the upper edge.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Dead-space forecast: residual is only valuable if future items can use it.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        // Sweet-spot reward: residuals in 8..=24 absorb typical small items well.
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        // Two-step lookahead: gaps that can host the next item once.
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
        // Divisibility test: penalize residuals below half the demand.
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        // Chain bonus: residual hosting next + a follow-up item.
        if next_item_size > 0 {
            let follow = mean_residual.max(4.0).min(40.0);
            if pr >= next_item_size as f64 + follow {
                score -= 16.0 * (1.0 - progress) * ((pr - next_item_size as f64 - follow) / cap_f).min(0.2).max(0.05) * 5.0;
            }
        }
        // Residual utility ratio vs mean open-bin residual.
        if bin_residual != bin_capacity {
            let mr = mean_residual.max(1.0);
            if pr < mr * 0.5 {
                score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
            }
        }
    }

    // Near-full consolidation: near-perfect fills rewarded, weighted late,
    // with an extended 5-10% band to squeeze remaining dead space.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Tight-fit precision band: almost exact fits get escalating reward.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // Perfect-pair lookahead: pair_gap matching next item, escalated late.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Scarcity-aware tightness boost: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    } else if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    score
}

