    // New-bin gate tightening — only allow a fresh bin to win when
    // no open bin achieves a near-perfect fit, and scale the gate by how much
    // of the stream remains (late stream: reuse bins aggressively).
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            // Large next item: a fresh bin is genuinely useful.
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Tight-fit precision band — residuals within 3 of the item
    // size (i.e., almost exact fit) get an extra escalating reward.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // Residual utility ratio — compare the post-residual against
    // the mean open-bin residual; residuals far below the mean are likely
    // unusable dead space, so penalize proportionally to the shortfall,
    // while residuals above the mean remain attractive hosts for future items.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Perfect-pair lookahead — when item + next exactly matches the
    // residual, escalate the reward late in the stream where every saved bin
    // counts more, and add a soft band for near-exact pairs (within 2).
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard — a new bin should only win when the
    // leftover capacity of the best open alternative would be genuinely
    // wasted; penalize opening a bin when some open bin's post-residual
    // would stay above half the next item's size (still usable space).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION: waste-forecast sweep — project the post-residual's usability
    // across the next two plausible item demands (next item and mean residual).
    // A residual that fails BOTH demands is almost certainly dead space, so
    // penalize it steeply with a quadratic ramp; a residual that satisfies
    // both gets a compounding host bonus, encouraging multi-item chains in
    // one bin and directly attacking the residual/dead-space weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let d1 = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        let d2 = mean_residual.max(4.0).min(cap_f * 0.4);
