        let fits2 = pr >= d2;
        if !fits1 && !fits2 {
            score += 22.0 * (1.0 - pr / d1.min(d2)) * (0.9 + progress);
        } else if fits1 && fits2 {
            score -= 10.0 * (1.0 - progress) * ((pr / cap_f).min(0.3) / 0.3);
        }
    }

    // MUTATION: late-stream consolidation surge — in the final third of the
    // stream, opening new bins is nearly always a loss; raise the fresh-bin
    // barrier progressively while boosting exact-fit rewards, so remaining
    // items are squeezed into existing residual pockets.
    if progress > 0.66 {
        let surge = (progress - 0.66) / 0.34;
        if bin_residual == bin_capacity {
            score += 45.0 * surge;
        } else if post_residual <= 12 {
            score -= 14.0 * surge;
        }
    }

    score
}

