    score += tightness * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize bins far below mean residual (avoid fragmenting many half-full bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Consolidation pressure grows with open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // When several bins can fit the item, prefer the emptiest reasonable bin.
    if fitting_bins_count > 2 {
        score += 0.35 * (bin_residual as f64 / cap_f) * 20.0;
    }

    // Dead-space hazard: residual gaps too small for typical future items are
    // the main source of wasted bins.
    if post_residual > 0 && post_residual < 20 {
        score += 18.0 + 25.0 * progress;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0 * progress;
        }
    }

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size {
            score -= 55.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        // Fresh-bin lookahead chain — prefer a fresh bin only when the
        // item + next pair fits cleanly, giving the next item a full
        // residual exactly equal to its size.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
        // MUTATION: tightened fresh-bin gate — with multiple fitting bins,
        // opening a new bin is only justified for a perfect or near-perfect
        // fill; scale the gate by remaining stream so late stream reuses bins.
        if fitting_bins_count > 1 {
            score += 30.0 * progress;
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score -= 25.0 * (1.0 - progress);
            }
        }
        // MUTATION: fresh-bin waste guard — a new bin should only win when the
        // leftover capacity of the best open alternative would be genuinely
        // wasted; penalize opening a bin when a fresh bin's post-residual
        // would still comfortably hold the next item.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
            }
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space, sharper near the upper edge.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Dead-space forecast: residual is only valuable if future items can use it.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        // Sweet-spot reward: residuals in 8..=24 absorb typical small items well.
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        // Fine-grained dead-gap gradient — smooth surcharge growing as the
        // gap shrinks toward zero; tiny 1-3 unit slivers punished hardest.
        if pr < 20.0 {
            score += (20.0 - pr) * 0.9 * (0.6 + progress);
        }
        // Two-step lookahead — bias toward gaps that serve the immediate future.
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Near-full consolidation: near-perfect fills rewarded, weighted late.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Scarce-fit competition — when few bins can host the item, prefer
    // filling the fullest feasible bin to preserve empty capacity.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // MUTATION: residual utility ratio — residuals far below the mean open-bin
    // residual are likely unusable dead space; penalize proportionally to the
    // shortfall, weighted early where fragmentation risk is highest.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION: perfect-pair lookahead — when item + next exactly matches the
    // residual, escalate the reward late in the stream; add a soft band for
    // near-exact pairs (within 2).
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION: combined residual-fit + lookahead synergy — reward placements
    // where the next item consumes the post-residual almost exactly, and
    // penalize placements whose residual cannot host the next item when
    // alternatives exist.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION: tight-fit precision band — residuals within 3 of the item
    // size (almost exact fit) get an escalating reward.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION: dead-space divisibility test — residuals below half the next
    // item's demand are near-certain waste; sharpen the penalty late.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        // Chain bonus: if the next item fits and leaves a still-usable
        // residual (>= 8), reward the two-step packing chain.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
