    // leftover capacity of the best open alternative would be genuinely
    // wasted; penalize opening a bin when some open bin's post-residual
    // would stay above half the next item's size (still usable space).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION: dead-space usability horizon — instead of only comparing the
    // post-residual to the next item, check whether it can host the next item
    // *or* the mean residual afterwards. Residuals that support a two-step
    // chain (next item then a mean-sized follow-up) are rewarded sharply;
    // residuals that fail even a single-step check are penalized harder late
    // in the stream where wasted space directly costs bins.
    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(1.0).min(cap_f * 0.5);
        if pr >= n + follow {
            // Two-step usable chain: strong compaction reward.
            score -= 12.0 * (1.0 + progress) * ((n + follow) / cap_f).min(0.3) * 4.0;
        } else if pr < n * 0.5 && pr < follow {
            // Single-step failure with no chain potential: hard penalty.
            score += 18.0 * (0.4 + 0.6 * progress) * (1.0 - pr / (n * 0.5).max(1.0));
        }
    }

    // MUTATION: residual-halving refinement — when the post-residual is an
    // even split candidate (close to half the mean residual), it is likely
    // to be split-consumable by two small follow-ups; give a mild reward
    // scaled by remaining stream so early packing favors such splits.
    if post_residual > 0 && open_bins_count > 2 {
        let pr = post_residual as f64;
        let half_mean = mean_residual.max(2.0) * 0.5;
        if half_mean >= 2.0 && (pr - half_mean).abs() <= 2.0 {
            score -= 7.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

