        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Exact-chain bonus — placing here lets the next item perfectly
    // consume the leftover; reward scaled by scarcity of fitting bins.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (fitting_bins_count.min(5) as f64 / 5.0);
    }

    // New-bin gate — early small items should consolidate.
    if bin_residual == bin_capacity {
        let small_early = item_size <= bin_capacity / 4 && progress < 0.5;
        if small_early {
