        }
    }

    // MUTATION (gen 16): tight-fit precision band — near-exact fits
    // (gap <= 3) get an escalating reward that grows late in the stream.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 16): residual utility ratio — penalize residuals far
    // below the mean open-bin residual (likely unusable dead space).
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 16): perfect-pair lookahead with near-exact band —
    // escalate when item+next matches the residual exactly or within 2.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 16): fresh-bin waste guard — penalize opening a new
    // bin when its leftover would still be usable by the next item.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
        // Late-stream consolidation pressure: fresh bins must earn their
        // place harder as the stream ends.
        if progress > 0.75 {
            score += 20.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: early in stream, consolidate; late, be flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect-fit reward: strongly favor bins where the item fills residual exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: quadratic decay of residual (dead space hurts non-linearly).
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward using bins that are already "small residue" (consolidation).
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate logic: only attractive if current fit is poor
    // (post_residual very small means good fit, so penalize opening new bins then).
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        // Penalize new bins generally, less so when item is large (poor fit anywhere).
        score += 150.0 * (1.0 - fit_quality) + 50.0;
        // If many bins are open with large mean residual, opening new is worse.
        score += open_bins_count as f64 * 5.0;
        score += mean_residual * 0.5;
        // Early stream: prefer consolidation into open bins.
        score += (1.0 - progress) * 80.0;
    }

    // Lookahead: if next item would exactly fit this bin's post-residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits after this placement: mild reward, scaled by leftover.
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward residue.
            score += 20.0;
        }
    }

    // Prefer bins whose residual is close to mean (avoid fragmenting outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 25.0;

    // Late stream: slight extra pressure to fill existing bins tightly.
    score += progress * (post_residual as f64) * 0.3;

    score
}

