pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;                       // normalized post residual in [0,1]
    let t = (step_index as f64) / (total_items as f64).max(1.0); // stream progress
    let fit = fitting_bins_count as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = 1.0 + t * (1.0 - t) * 4.0; // bumps mid-stream, smooth
    let mut score = pr * progress_poly;

    // Penalize small post-residuals quadratically (dead space) more late in stream
    let dead = (1.0 - base).powi(2);
    score += 30.0 * dead * (0.5 + t);

    // Reward tight fits when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    score -= 5.0 / (fit + 1.0);

    // Lookahead coupling: reward leaving space for next item, smoothly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt) / cap;
        let reward = (-2.0 * gap * gap).exp();
        score -= 8.0 * reward * (1.0 + t);
    }

    // Slight preference for consolidating when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - base);

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 12.0 * (1.0 - t) + 3.0;
    }

    score
}

