    // New-bin gate tightening.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Tight-fit precision band.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION: residual utility ratio.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION: perfect-pair lookahead.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION: fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // NEW MUTATION: dead-space minimization via post-residual reusability
    // forecast — estimate how many future items (proxied by mean residual)
    // the post-residual could still host; reward bins whose leftover space
    // remains multi-use, penalize single-use or zero-use leftovers.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let reuse_count = (pr / mr).floor().min(4.0);
        score -= 5.0 * reuse_count * (0.6 + 0.4 * progress);
        // Zero-reuse leftover is pure waste: escalate the penalty late.
        if reuse_count < 1.0 {
            score += 30.0 * (1.0 - pr / mr.max(pr)) * (0.5 + progress);
        }
    }

    // NEW MUTATION: waste-avoidance pairing — when the next item would leave
    // a residual smaller than the smallest plausible item (mean residual /
    // 3), the following placement is likely forced into a fresh bin; prefer
    // placements that instead keep the post-residual within the reusable band.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let after_next = pr - n;
        if after_next > 0.0 && after_next < mean_residual.max(2.0) / 3.0 {
            score += 12.0 * (1.0 - after_next / (mean_residual.max(2.0) / 3.0)) * (0.7 + 0.3 * progress);
        }
    }

    // NEW MUTATION: scarcity-driven fresh-bin suppression — when only a few
    // open bins can host the item, opening a new bin fragments capacity that
    // may be needed for upcoming large items; make the fresh-bin candidate
    // strictly less attractive unless its post-residual is tiny.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 && fitting_bins_count <= 2 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post > bin_capacity / 4 {
            score += 22.0 * (1.0 - progress);
        }
    }

    score
}

