            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        // Fresh-bin pair-fit chain.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
        // New-bin gate tightening: late stream reuses bins aggressively.
        if fitting_bins_count > 1 {
            score += 30.0 * progress;
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score -= 25.0 * (1.0 - progress);
            }
        }
        // Fresh-bin waste guard: only open a bin when the best open alternative
        // would leave genuinely wasted space.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
            }
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space with a sharper gradient.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dual-window chain bonus.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    // Tight-fit precision band.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // Residual utility ratio vs mean open-bin residual.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Perfect-pair lookahead with soft near-exact band.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION: late-stream consolidation surge — in the final third of the
    // stream, escalate the penalty on any post-residual that cannot host the
    // next item, forcing tighter fills when the remaining slack is what
    // decides whether an extra bin is opened at all.
    if post_residual > 0 && next_item_size > 0 && progress > 0.66 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr < n {
            score += 22.0 * (1.0 - pr / n) * (progress - 0.66) * 3.0;
        }
    }

    // MUTATION: near-exact residual band refinement — extend the tight-fit
    // precision band from gap<=3 to gap<=5 with a decaying gradient, catching
    // the 4-5 unit fits the parent treated as ordinary placements.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap > 3 && gap <= 5 {
            score -= 8.0 * (6.0 - gap as f64) * (0.7 + 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear polynomial in normalized post-residual
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr;          // penalize large dead space quadratically
    score -= 25.0 * norm_pr * (1.0 - norm_pr);  // reward near-perfect fills (small post_residual)

    // Smooth coupling with stream progress: early on, tolerate loose fits; late, pack tightly
    let tightness = 1.0 - progress;
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);   // extra early tolerance for big residuals
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress; // reward tight fits late in stream

    // Lookahead: bonus if next item fits into post_residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0);
        let gap = (next_item_size as f64 - pr).abs();
        let coupling = 1.0 / (1.0 + gap / 20.0);
        score -= 15.0 * coupling * (1.0 - fits_next / cap);
        score += 10.0 * (next_item_size as f64 / cap) * (1.0 - coupling);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Penalize many open bins mildly, scaled by mean residual mismatch
    let mismatch = (mean_residual - pr).abs() / cap;
    score += 5.0 * (open_bins_count as f64 / 20.0) * (0.5 + mismatch);

    // New-bin candidate: smooth penalty so it's chosen only when fits are very poor
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - norm_pr) * (1.0 + tightness);
    }

    score
}

