pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo arithmetic) ---
    // Residuals that are "nice" multiples of common item classes (10/20/25/50)
    // are more reusable. Reward residuals divisible by 10 or 25.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 4.0;
            if pr % 50 == 0 { score -= 3.0; }   // half-capacity reusable
        }
        if pr % 25 == 0 { score -= 2.5; }
        // Penalize awkward residues (dead-space risk)
        let r = pr % 10;
        if r != 0 { score += (5 - r as i32).abs() as f64 * 0.6; }
    } else {
        // Perfect closure of a bin is excellent
        score -= 12.0;
    }

    // --- Fraction-of-capacity coupling ---
    let fill = 1.0 - (post_residual as f64) / cap;
    // Reward high fill fraction nonlinearly
    score -= 8.0 * fill * fill;

    // --- Lookahead compatibility: can next item fit in the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item still fits: mild reward, scaled by how well it fits
            let slack = (pr - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize proportionally to overflow gap
            let gap = (next_item_size - pr) as f64;
            score += 0.08 * gap;
        }
    } else {
        // Last item: prefer minimal final residual
        score += 0.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- Competition pressure: many open bins -> consolidate, prefer fuller bins ---
    if open_bins_count > 1 {
        let pressure = (open_bins_count as f64).ln();
        score -= pressure * fill * 2.0;
    }

    // --- Mean residual coupling: prefer bins whose residual deviates low from mean ---
    let resid = post_residual as f64;
    if resid > mean_residual {
        score += 0.05 * (resid - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - resid);
    }

    // --- Integer-division threshold on post_residual ---
    // Very small residuals (< 10) are near-dead space; but if they close the bin it's fine.
    if pr > 0 && pr < 10 {
        score += 6.0;
    }

