        // Fresh-bin waste guard: only open when the best open alternative
        // would leave unusable space; if a fresh bin's leftover could still
        // host the next item, penalize opening it when open bins exist.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
