    // residual are likely unusable; sharpen the penalty late in the stream
    // where dead space directly translates into extra bins.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 14.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION: late-stream compaction surge — as the stream nears its end,
    // escalate the reward for near-perfect fills so remaining capacity is
    // squeezed into existing bins instead of spawning new ones.
    if progress > 0.6 && post_residual > 0 && bin_residual != bin_capacity {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.25 {
            score -= 10.0 * (0.25 - frac) * (progress - 0.6) * 5.0;
        }
    }

    score
}

