    // the main source of wasted bins.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // When several bins can fit the item, prefer the emptiest reasonable bin.
    if fitting_bins_count > 2 {
        score += 0.35 * (bin_residual as f64 / cap_f) * 20.0;
    }

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        // Fresh-bin pair-fit chain: open a fresh bin when item + next fits cleanly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
        // MUTATION: fresh-bin waste guard — only allow a fresh bin to win when
        // no open bin's post-residual would remain genuinely usable for the
        // next item; scale the guard late in the stream.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
            }
        }
        // MUTATION: late-stream gate — fresh bins must beat open bins by a
        // growing margin as the stream progresses; reuse wins late.
        if fitting_bins_count > 1 {
            score += 30.0 * progress;
            if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
                score -= 25.0 * (1.0 - progress);
            }
        }
    }

