            let chain = (post_residual - next_item_size) as f64;
            score -= 50.0 - 0.3 * chain;
        } else {
            // Next item won't fit in the residual: penalize relative to overshoot.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }

        // Bonus if item + next item together perfectly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 120.0;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // attractive targets (absorb space), bins below mean are less so.
    let rel = bin_residual as f64 - mean_residual;
    score -= 0.15 * rel;

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and the item is large (better to keep small items for filling later).
    if bin_residual == bin_capacity {
