    if next_item_size > 0 && fitting_bins_count >= 1 {
        let fits_next_here = post_residual >= next_item_size;
        if !fits_next_here && bin_residual != bin_capacity && post_residual > 0 {
            let pr = post_residual as f64;
            let n = next_item_size as f64;
            score += 9.0 * (1.0 - pr / n) * (0.6 + 0.6 * progress);
        }
    }

    score
}

