pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fits).
    let mut score = post;

    // Smooth non-linear reward for very tight fits (post_residual near zero).
    score -= 40.0 * (1.0 - norm_post).powi(6) * (1.0 - norm_post).powi(2);

    // Penalize awkward dead space: residuals that are small-but-not-tiny are worst.
    let dead = (norm_post * (1.0 - norm_post)).sqrt();
    score += 12.0 * dead * (1.0 - (post / 50.0f64.min(cap)).abs().min(1.0));

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let snug = 1.0 - ((post - next) / cap);
            score -= 25.0 * snug * (1.0 - progress * 0.5);
        } else {
            // Post-residual too small for next item: mild penalty scaled by overflow.
            score += 8.0 * ((next - post) / cap).min(1.0);
        }
    } else {
        // Last item: strongly reward using an existing bin.
        score -= 30.0;
    }

    // Last-chance bin: this is the only bin that fits — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    // and when other fitting bins exist.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln1p();
        score += 55.0 + 25.0 * progress + 6.0 * open_pressure;
        if fitting_bins_count == 0 {
            score -= 90.0; // nothing fits elsewhere; new bin is correct
        } else if next_item_size > 0 && (next_item_size as f64) > post {
            score -= 20.0; // current bins would leave unusable space anyway
        }
    }

    // Mild stream-progress coupling: later in stream, be more conservative
    // about leaving medium residuals (hard to fill later).
    score += 10.0 * progress * norm_post * (1.0 - norm_post);

    // Prefer bins with residuals close to item (relative tightness).
    let rel_fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * rel_fit.min(1.0) * (1.0 - progress);

    score
}

