    if post_residual == 0 {
        score -= 60.0;
    }
    // Class 2: residual in [1..=5] -> near-perfect, mild reward.
    else if post_residual <= 5 {
        score -= 8.0;
    }
    // Class 3: residual is an exact harmonic fraction of capacity
    // (25, 50, 75) -> still reusable by common item sizes.
    else if post_residual * 4 % bin_capacity == 0 {
        score -= 6.0;
    }
    // Class 4: dead-zone residuals just above common item sizes
    // (e.g. 11..=19, 21..=29) are hard to fill -> penalize.
    let mod10 = post_residual % 10;
    if mod10 >= 1 && mod10 <= 9 && post_residual >= 11 {
        score += (10 - mod10) as f64 * 0.6;
    }

    // Lookahead coupling: reward if the next item fits exactly into
    // the post-residual (harmonic chaining), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= (10 - gap) as f64 * 1.2;
            } else {
                score += gap as f64 * 0.15;
            }
        }
        // If next item can't fit this residual anyway, residual class
        // matters less; slight normalization.
        if next_item_size > post_residual {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current residual is truly bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if mean residual across open bins is small (bins nearly
        // full), opening fresh is fine.
        if mean_residual < 10.0 {
            score -= 20.0;
        }
        // Early in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score += 8.0;
        }
    }

    // Slight preference for tighter bins overall.
    score -= (cap - bin_residual as f64) * 0.05;

    score
}

