    // (tiny post-residual) but the next item is large, prefer this bin over
    // others since the leftover would be unusable anyway; conversely when
    // the post-residual is large and the next item is small, mild penalty
    // to avoid hoarding space that small items could fragment.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0 && pr < n * 0.25 && n > cap_f * 0.35 {
