    // every open bin with slack is a potential wasted bin; escalate the
    // preference for bins whose post-residual is smallest relative to the
    // field of fitting bins.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 4.0 * progress;
    }

    score
}

