    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin is attractive early or when
    // no open bin fits well, but should be avoided when an open bin gives
    // a decent fit (post_residual small) to prevent bin explosion.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 25.0 * progress;
