        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard — only open a new bin when the leftover
    // capacity would be genuinely wasted by the open alternatives.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION (gen 20): triple-fit chain anticipation — reward residuals
    // that can host the next item AND leave a still-usable remainder
    // (>= mean residual / 2), compounding the lookahead synergy with a
    // late-stream emphasis where compaction matters most.
    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let tail_floor = (mean_residual.max(1.0) * 0.5).min(12.0);
        if pr >= n + tail_floor {
            let usable_tail = pr - n;
            score -= 11.0 * (usable_tail / cap_f).min(0.15).max(0.02) * 40.0 * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 20): mid-band smoothing — replace the hard dead-space
    // cliff at 10 with a continuous gradient so residuals just above the
    // cliff are not over-punished, reducing fragmented half-empty bins.
