        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits, but leaves more waste afterward.
        score -= 50.0 - 0.5 * ((post_residual - next_item_size) as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
