    // scaled by how close we are to the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 20.0 + 30.0 * progress;
    }

    // Reward bins whose residual is already below average (well-worn bins):
    // packing into them keeps fresh large residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score += 3.0;
    }

