    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Perfect-fit bonus: exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that no plausible future item can use.
    // Small residuals (< 10) are dead space unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    // instead of opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * tight;
    }

    // New-bin candidate handling: penalize opening a new bin when
    // open bins fit well, but allow it when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty for wasting a fresh bin on a small item.
        score += 30.0 - 20.0 * (item_size as f64 / cap);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Early in the stream, opening bins is cheaper (build inventory).
        score -= 20.0 * (1.0 - progress) * (1.0 - progress);
        // If mean residual across open bins is small (bins nearly full),
        // a new bin is reasonable.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Reward using bins whose residual matches the item well.
        let waste_ratio = (post_residual as f64) / cap;
        score += 12.0 * waste_ratio;

        // Lookahead: if the next item fits exactly into post_residual,
        // this placement sets up a perfect follow-up.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 35.0;
            } else if next_item_size <= post_residual {
                score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            } else {
                // Next item won't fit here; residual becomes dead space risk.
                score += 6.0 * waste_ratio;
            }
