        // Favor filling bins that are already below mean residual
        // (balance load toward fuller bins).
        score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

        // Late in the stream, consolidate: prefer fullest bins.
        score += 10.0 * progress * (bin_residual as f64 / cap);
    }

    // Mild penalty for proliferating bins mid-stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
