    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION: dead-space quantization trap — post-residuals that are too
    // small to host the mean-sized follow-up item yet too large to be
    // "nearly full" are the main source of waste. Apply a quadratic
    // penalty in the trap band [10, mean_residual) that tightens late.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(6.0);
        if pr >= 10.0 && pr < mr {
            let depth = 1.0 - pr / mr;
            score += 22.0 * depth * depth * (0.7 + 0.6 * progress);
        }
        // Complementary reward: residuals that can host the mean item with
        // room to spare are prime consolidation targets.
        if pr >= mr {
            score -= 6.0 * ((pr - mr) / cap_f).min(0.15) * (1.0 + progress);
        }
    }

    // MUTATION: two-step chain lookahead — prefer placements whose
    // post-residual exactly fits next_item + mean_residual (a plausible
    // two-item continuation), scaling with remaining stream length.
    if post_residual > 0 && next_item_size > 0 && step_index + 2 < total_items {
        let chain_target = next_item_size as f64 + mean_residual.max(4.0);
        let gap = (post_residual as f64 - chain_target).abs();
        if gap <= 4.0 {
            score -= 20.0 * (1.0 - gap / 5.0) * (1.0 - progress);
        }
    }

    score
}

