        let third = mean_residual.max(3.0).min(30.0);
        if pr >= n + follow + third {
            score -= 10.0 * (1.0 - 0.5 * progress) * ((pr - n - follow - third) / cap_f).min(0.15).max(0.03) * 6.0;
