    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residue 0) heavily rewarded.
    let r = post_residual;
    if r == 0 {
        score -= 1000.0; // exact fit: perfect closure
    } else if r <= 5 {
        score -= 40.0; // near-perfect fit, tiny dead space
    }

    // Modulo arithmetic on post_residual: residuals that are "usable" sizes
    // (multiples of common item classes) are less dead than odd leftovers.
    let usable = |x: u32| -> bool {
        x % 10 == 0 || x % 5 == 0 || x >= 10
    };
    if r > 0 {
        if usable(r) {
            score -= 10.0;
        } else {
            score += 25.0; // odd dead space penalized
        }
    }

    // Integer division thresholds: classify residual into harmonic bands.
    let band = r / 10; // 0..10
    score += match band {
        0 => -20.0,
        1 => -10.0,
        2 => 0.0,
        3 => 5.0,
        _ => 10.0,
    } as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // next item fits: residual quality matters; prefer small leftover after that
        let post2 = r - next_item_size;
        score -= 50.0 + post2 as f64 * 0.5;
    } else {
        // next item cannot use this residual: penalize proportionally
        score += (r as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it attractive only when current bins are fragmented
    // or this is a big item better isolated.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size >= 60 || (r > 0 && r < 10) {
            score -= 80.0; // isolate big/awkward items in fresh bins
        } else {
            score += 60.0 + open_bins_count as f64 * 2.0;
        }
        let _ = fragmentation;
    }

    // Late-stream consolidation: prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.4;
    score -= progress * 5.0;

    // Prefer bins tighter than average (best-fit flavor with mean coupling).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

