    if post_residual > 0 && next_item_size > 1 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).floor();
        if k >= 2.0 {
            let rem = pr - k * n;
            if rem == 0.0 {
                score -= 14.0 * (1.0 - progress) * (k / 4.0).min(1.0);
            } else if rem <= 2.0 {
                score += 6.0 * (1.0 - rem / 3.0);
