        }
    }

    // MUTATION (gen 22): fresh-bin exact-pair trigger — open a new bin
    // only when it enables an exact two-item fill (item + next == capacity)
    // or when the next item is large and no open bin can host it later.
    if bin_residual == bin_capacity && next_item_size > 0 {
        if item_size + next_item_size == bin_capacity {
            score -= 90.0 * (1.0 - 0.5 * progress);
        }
        if next_item_size > bin_capacity / 2 && item_size <= bin_capacity - next_item_size {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 22): waste-avoidance gradient on open bins — prefer
    // the open bin whose post-residual is the smallest usable gap; bins
    // leaving a gap just under the next item size are the worst outcome.
    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr < n && pr >= n * 0.7 {
            score += 10.0 * (pr / n - 0.7) / 0.3 * (0.6 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

