    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 8.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage reuse.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when no open bin fits well
    // (poor fit here means large dead space) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size {
            let pr = bin_residual - item_size;
            (pr > 0 && pr < 10) as i32 as f64 * 40.0 + (pr >= 10 && pr < 20) as i32 as f64 * 12.0
