        score += 60.0 - poor_fit - 20.0 * (step_index as f64 / (total_items as f64).max(1.0));
    }

    // Slight preference for bins whose residual deviates from mean (consolidate similar gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

