    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dual-window chain bonus.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    // New-bin gate tightening.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Tight-fit precision band.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // Residual utility ratio vs. mean open-bin residual.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Perfect-pair lookahead with near-exact band.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION: usable-dead-space forecast — a leftover residual is only
    // valuable if some future item can actually land in it. Estimate the
    // stream's typical small-item demand as min(next, mean_residual) and
    // reward residuals that remain hostable for such demand, while sharply
    // penalizing residuals that fall into the "orphan band": too large to be
    // ignored, too small to host the smallest plausible future demand.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 {
            (next_item_size as f64).min(mean_residual.max(1.0))
        } else {
            mean_residual.max(1.0)
        };
        if pr >= demand {
            // Hostable: mild reward proportional to how many multiples of
            // the demand still fit, capped to avoid favoring loose bins.
            let hosts = (pr / demand).min(3.0);
            score -= 5.0 * hosts * (0.4 + 0.6 * progress);
        } else {
            // Orphan band: dead space that likely can never be filled.
            score += 22.0 * (1.0 - pr / demand) * (0.7 + 0.6 * progress);
        }
    }

    // MUTATION: adaptive new-bin trigger — open a fresh bin only when the
    // item is large relative to capacity AND no open bin leaves a usable
    // post-residual; scale the barrier with the remaining stream so early
    // consolidation is favored but late large-item placement is cheap.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        let item_frac = item_size as f64 / cap_f;
        let barrier = 20.0 + 60.0 * item_frac * (1.0 - progress);
        score += barrier;
        // If the fresh bin would be nearly full after placement, it is a
        // good deal regardless of progress — reward instead of penalize.
        if (bin_capacity - item_size) as f64 <= cap_f * 0.15 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer minimal post residual, with non-linear sharpening.
    let mut score = pr_norm.powf(1.5 + 2.0 * progress);

    // Smooth polynomial coupling: residual waste weighted against stream progress.
    // Late in the stream, dead space is more costly (fewer chances to fill it).
    let waste_penalty = pr_norm * pr_norm * (0.5 + 1.5 * progress);
    score += waste_penalty;

    // Reward near-perfect fits via a smooth bell-shaped bonus around small residuals.
    let fit_bonus = (-8.0 * pr_norm).exp();
    score -= 3.0 * fit_bonus * (1.0 + progress);

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (next_item_size as f64 - pr).abs() / cap;
        score -= 2.0 * tight * tight;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    }

    // Scarcity pressure: many open bins -> prefer reusing existing ones.
    let scarcity = (open_bins_count as f64).ln1p();
    score += 0.3 * scarcity * pr_norm;

    // New-bin candidate: penalize relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress) + 0.5 * mean_residual / cap;
    } else {
        // Slight reward when this bin's residual is below average (tight fit).
        score += 0.5 * ((bin_residual as f64) - mean_residual) / cap;
    }

    score
}

