    // leftover capacity of the best open alternative would be genuinely
    // wasted; penalize opening a bin when some open bin's post-residual
    // would stay above half the next item's size (still usable space).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // NEW MUTATION: residual reusability ladder — grade post-residuals by
    // how many plausible future items (next size or mean residual) they can
    // still host; residuals hosting zero future items are dead space and get
    // a sharpened penalty, while residuals hosting two or more get a bonus,
    // steering placement toward bins that remain productive after this item.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        let m = mean_residual.max(4.0).min(50.0);
