        if !hosts_next && !hosts_mean {
            score += 16.0 * (0.7 + 0.5 * progress);
        } else if hosts_next && hosts_mean {
            score -= 10.0 * (1.0 - 0.5 * progress);
        } else if hosts_mean && !hosts_next && n > 0.0 && pr < n {
            // Residual fits average items but not the immediate next item:
            // mild penalty so we prefer bins that accommodate the known next.
            score += 5.0 * (1.0 - pr / n.max(1.0));
        }
    }

    // NEW MUTATION: waste-floor guard — post-residuals that fall into the
    // narrow band just below the smallest plausible item (mean residual)
    // are almost certainly stranded; apply a quadratic penalty scaled by
    // how close they are to that floor, strongest early in the stream.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let floor = mean_residual.max(6.0).min(45.0);
        if pr < floor {
            let deficit = (floor - pr) / floor;
            score += 22.0 * deficit * deficit * (1.1 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "harmonic slots"
    let pr = post_residual;
    let harmonic = pr % 10;
    let class_id = pr / 10; // integer-division threshold class (0..10)

    // Perfect fits are divine: crush the score.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 120.0;
    }

    // Reward residuals that sit exactly on harmonic boundaries (multiples of 10/20/25)
    if pr % 20 == 0 && pr > 0 {
        score -= 60.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 45.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 25.0;
    } else {
        // Dead-space penalty grows for awkward residues (harmonic mismatch)
        score += (10 - harmonic) as f64 * 3.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr && pr - next_item_size <= 5 {
            score -= 150.0;
        } else if next_item_size > pr {
            // next item won't fit here: residual is likely dead weight
            let waste = pr as f64 / bin_capacity as f64;
            score += waste * 80.0;
        }
        // Harmonic pairing: next item leaves a multiple-of-10 residual
        if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 70.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Penalize very low class bins when many bins are open (fragmentation control)
    if class_id == 0 && pr > 0 {
        score += 40.0 * (open_bins_count as f64).sqrt();
    }

    // Stream progression: early on, be picky about tight fits; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0 * (1.0 - pr as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is huge or no open bin is decent.
    if bin_residual == bin_capacity {
        let base = 55.0 + item_size as f64 * 0.9;
        let fit_pressure = if fitting_bins_count == 0 { -200.0 } else { fitting_bins_count as f64 * 25.0 };
        score = base + fit_pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 40.0; // big next item: keep a fresh bin around
        }
    }

    // Mild tie-breaker toward bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

