    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit any plausible item (min size 1),
    // but the worst waste is mid-sized gaps that no small item exactly fills.
    let r = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Tiny gap: nearly unusable, penalize extra.
        score += 50.0;
    } else {
        // Usable gap: mild reward proportional to how well it matches next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            // Gap can host the lookahead item: reward.
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Gap too small for next item: dead space risk.
            score += 0.8 * r;
        }
