    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open bins pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize opening new ones less, but reward reuse).
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when few bins open or item fits poorly elsewhere.
        score += 40.0 + 2.0 * ob;
        if fitting_bins_count == 1 {
            // Only alternative is a poor fit; allow new bin if item is large.
            score -= 35.0 * (item_size as f64 / 100.0);
        }
    } else if fitting_bins_count == 1 {
        // This is the last bin that can fit the item: strong reward to avoid new bin.
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as stream progresses, favor closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

