        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dual-window chain bonus — post residual hosting next item plus a
    // plausible follow-up (proxied by mean residual) earns a compounding
    // reward, strongest early when more stream remains to pack.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    // New-bin gate tightening — fresh bins only win when no open bin
    // achieves a near-perfect fit; gate scales with remaining stream.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Tight-fit precision band.
    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.8 + 0.4 * progress);
        }
    }

    // Residual utility ratio.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Perfect-pair lookahead with near-exact band.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION (gen 24): two-step horizon fit — measure how well the
    // post-residual divides into the next item and a mean-sized follow-up.
    // A post-residual that leaves a small remainder after absorbing both
    // is a high-quality chain slot; reward it proportionally, stronger
    // early. This couples fine-grained residual fitting with lookahead.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(1.0);
        if pr >= n + follow {
            let rem = pr - n - follow;
            if rem <= 4.0 {
                score -= 14.0 * (1.0 - rem / 5.0) * (0.6 + 0.6 * progress);
            }
        }
        // Exact triple fill: post-residual equals next + follow precisely.
        if (pr - n - follow).abs() <= 1.0 {
            score -= 20.0 * (0.7 + progress);
        }
    }

    // MUTATION (gen 24): waste-quantization penalty — a post-residual that
    // cannot host the next item but is only slightly smaller than it is the
    // worst outcome (almost usable, fully wasted). Penalize the near-miss
    // band [next-6, next) sharply, especially late in the stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = next_item_size - post_residual;
        if miss <= 6 {
            score += 10.0 * (7.0 - miss as f64) * (0.5 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimize dead space non-linearly).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 40.0;

    // Exact fit: overwhelming preference.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 500.0; // perfect chain: next item fits exactly afterwards
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item won't fit: penalize proportionally to leftover dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward moderate residuals that keep future flexibility relative to mean residual
        if post_residual as f64 >= mean_residual {
            score -= 5.0;
        } else {
            score += (mean_residual - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate has residual == capacity).
    if bin_residual == bin_capacity {
        score += 60.0;
        // But allow new bin early in stream or when existing residuals are all tiny (fragmented).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 && post_residual > 20 {
            score -= 80.0;
        }
        if progress < 0.05 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter existing bins (best-fit flavor).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: very strong reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

