    // Residual utility ratio — residuals far below the mean are likely
    // unusable dead space, so penalize proportionally to the shortfall,
    // while residuals above the mean remain attractive hosts for future items.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Perfect-pair lookahead — when item + next exactly matches the
    // residual, escalate the reward late in the stream where every saved bin
    // counts more, and add a soft band for near-exact pairs (within 2).
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard — a new bin should only win when the
    // leftover capacity of the best open alternative would be genuinely
    // wasted; penalize opening a bin when some open bin's post-residual
    // would stay above half the next item's size (still usable space).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size as u32 {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION 1: multi-item chain horizon — instead of only checking whether
    // the post-residual hosts the next item, estimate how many future items of
    // mean size it could absorb; each additional absorbable item compounds a
    // reward, pushing the heuristic toward residuals that act as useful
    // "mini-bins" rather than one-shot fits. This directly attacks the
    // diagnosed dead-space weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let unit = if next_item_size > 0 && next_item_size <= post_residual {
            next_item_size as f64
        } else {
            mean_residual.max(3.0)
        };
        let absorbable = (pr / unit).floor();
        if absorbable >= 1.0 {
            score -= 9.0 * absorbable.min(4.0) * (0.6 + 0.6 * progress);
        } else {
            // Residual cannot host even one plausible item: escalate the
            // dead-space penalty, scaled by how much capacity is stranded.
            score += 12.0 * (pr / cap_f) * (1.0 + progress);
        }
    }

    // MUTATION 2: parity-aware new-bin gate — opening a fresh bin is only
    // attractive when the resulting fresh post-residual is large enough to be
    // reusable by the stream's typical demand (mean residual); otherwise the
    // fresh bin would just create another stranded fragment. This tightens
    // the new-bin decision late and under fragmentation pressure.
    if bin_residual == bin_capacity {
        let fresh_post = (bin_capacity - item_size) as f64;
        let demand = mean_residual.max(3.0);
        if fresh_post < demand {
            score += 45.0 * (1.0 - fresh_post / demand) * (0.7 + progress);
        }
        if open_bins_count > 6 {
            // With many open bins, consolidation beats expansion.
            score += 20.0 * (1.0 - progress);
        }
    }

    // MUTATION 3: stranding avoidance for large items — when the current item
    // is big (> half capacity), the post-residual is almost certainly dead
    // space; prefer the open bin whose residual is closest to the item size
    // so the leftover is minimized, via a quadratic squeeze on the leftover.
    if item_size > bin_capacity / 2 && bin_residual != bin_capacity {
        let leftover = post_residual as f64;
        score += 0.35 * (leftover * leftover) / cap_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill of this bin after placement.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward near-perfect packing: strongly subtract when post_residual is tiny.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize large dead space relative to the smallest plausible item (1..100 range).
    let dead_penalty = (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
    score += dead_penalty;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (next_item_size as f64 - post_residual as f64).abs() / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by wasted potential.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer the fullest bin, open nothing new.
        score -= 40.0 * fill;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (especially late in the stream where opening bins is less recoverable).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 40.0 * t;
    }

    // New-bin candidate handling: brand-new empty bin. Only attractive when no
    // open bin offers a decent fit, or when open bins are nearly all full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a bin early (more future to fill it) and when
        // existing bins are crowded (high mean fill / low mean residual).
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 30.0 * (1.0 - t) * mean_fill;
        // If many bins fit the item, discourage opening a new one.
        score += 6.0 * fitting_bins_count as f64;
