    // current residual earns an escalating late bonus, complementing the
    // post-residual chain logic with pre-placement precision.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

