    // Dead-space slope escalation on the diagnosed weak zone (9..25).
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 34.0 * g * (1.0 - g) * (0.7 + progress);
    }

    // Exact-fill chain escalation.
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }

    // Sub-4 precision tightening.
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }

    // Fresh-bin threshold coupling.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    // MUTATION (gen 27): residual-fit + lookahead synthesis — combine a
    // continuous fit-quality term over the full post-residual range with a
    // forward usability forecast: reward placements whose post-residual can
    // absorb the next item with minimal leftover, penalize those that leave
    // a gap just below the next item (worst-case dead space).
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n {
            let after = pr - n;
            // Reward proportionally to how fully the next item consumes the gap.
            score -= 10.0 * (1.0 - after / pr) * (0.6 + 0.4 * progress);
        } else {
            // Gap just below the next item is the worst outcome: dead space.
            let deficit = (n - pr) / n;
            if deficit < 0.3 {
                score += 22.0 * (1.0 - deficit / 0.3) * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 27): two-step lookahead compaction — when the current
    // placement leaves room for the next item AND the remainder after that
    // is small (<= 6), the bin hosts two items almost perfectly; reward
    // strongly, escalating late when bins are scarcer.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after <= 6 {
            score -= 20.0 * (1.0 - after as f64 / 7.0) * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 27): fresh-bin scarcity gate — only allow opening a new
    // bin when the item truly cannot consolidate; under scarcity of fitting
    // bins with a large next item, tilt harder against the fresh-bin call
    // so residual space is reused before spawning new bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.4 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 {
            score += 12.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 27): mid-gap usability sharpening — residuals in the
    // 20..35 band are the most likely to strand; make the penalty ramp
    // continuously with the deficit against the next item instead of the
    // flat band, coupling the fit and lookahead signals.
    if post_residual >= 20 && post_residual <= 35 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr < n {
            score += 9.0 * (1.0 - pr / n) * (0.6 + 0.4 * progress);
        } else if pr - n <= 10.0 {
            score -= 6.0 * (1.0 - (pr - n) / 11.0) * (0.6 + 0.4 * progress);
        }
    }

    score
}

