    // Exact-fill cascade escalation — when the current placement empties
    // the bin AND the next item exactly fills another residual (proxied by
    // mean residual), reward the chain harder late.
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }

    // Sub-8 precision tightening — prefer near-unrecoverable 1..=3 gaps
    // over stranding a 4..=7 gap.
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }

    // Fresh-bin threshold coupling — tilt against opening a bin whose
    // post-residual the next item cannot use.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    // MUTATION (gen 27): consolidation-weighted fit ratio — combine the
    // fine-grained tightness of the placement with open-bin scarcity:
    // when few bins can host the item, squeeze the chosen bin harder so
    // the leftover stays as small as possible (reduces dead space ratio).
    if bin_residual != bin_capacity && fitting_bins_count >= 1 {
        let fill = item_size as f64 / bin_residual as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64).sqrt();
        if fill > 0.7 {
            score -= 20.0 * (fill - 0.7) * (1.0 + scarcity) * (0.6 + progress);
        } else if fill < 0.4 {
            score += 8.0 * (0.4 - fill) * scarcity * (1.2 - progress);
        }
    }

    // MUTATION (gen 27): residual parity with next-item lookahead — when
    // the post-residual is a near-multiple of the next item, the gap will
    // likely be fully consumed in the following steps; reward proportionally.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).floor();
        let rem = pr - k * n;
        if k >= 1.0 && rem <= 2.0 {
            score -= 14.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) * (k / (k + 1.0));
        }
    }

    // MUTATION (gen 27): mean-residual pull — nudge bin selection toward
    // bins whose post-residual lands close to the current mean residual,
    // keeping the residual distribution compact and reusable.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let d = (pr - mr).abs();
        if d <= 6.0 {
            score -= 10.0 * (1.0 - d / 7.0) * (0.6 + 0.4 * progress);
        }
    }

    score
}

