    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
            score -= 25.0 * (0.4 + progress);
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
            // Post-fit cascade: residual after hosting next item still useful.
            let after = slack;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
            // Stranding a gap the next item cannot use — penalize under scarcity.
            if fitting_bins_count > 1 {
                score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
