    }

    // Perfect-pair lookahead.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // Residual utility ratio.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Late-stream consolidation gate.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 24, reinforced gen 26): exact-fill cascade bonus.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }

    // MUTATION (gen 24): medium-gap divisibility.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 24): fresh-bin final gate near stream end.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }

    // MUTATION (gen 26, reinforced gen 28): dead-space slope escalation.
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }

    // MUTATION (gen 26): exact-fill chain escalation.
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }

    // MUTATION (gen 26): sub-8 precision tightening.
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }

    // MUTATION (gen 26): fresh-bin threshold coupling.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    // MUTATION (gen 28): two-step chain fit.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let follow = mean_residual.max(3.0).min(50.0);
        if after >= follow {
            score -= 10.0 * (1.0 - (after - follow) / cap_f) * (1.2 - 0.6 * progress);
        }
    }

    // MUTATION (gen 28): stranded-gap classification.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mr = mean_residual.max(1.0);
        if (post_residual as f64) < mr * 0.5 && fitting_bins_count > 1 {
            score += 9.0 * (1.0 - post_residual as f64 / (mr * 0.5)) * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 28): near-full escalation.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 8.0 * (6.0 - post_residual as f64) * (0.5 + progress);
    }

    // MUTATION (gen 29): global-fill efficiency gradient — compare this bin's
    // fill fraction against the fleet-wide average fill; choosing the bin that
    // ends closest to (or above) the running average fill consolidates the
    // fleet and directly attacks the residual-variance weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let avg_fill = (cap_f - mean_residual).max(0.0);
        let this_fill = item_size as f64 / bin_residual as f64;
        let target = (avg_fill / cap_f).clamp(0.2, 0.95);
        if this_fill >= target {
            score -= 14.0 * (this_fill - target).min(0.4) * (0.8 + 0.6 * progress);
        } else {
            score += 7.0 * (target - this_fill) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 29): modular residue alignment — when the post-residual is
    // a near-exact multiple of the mean residual, future items drawn near the
    // mean can chain-fill it; reward such divisible gaps, especially early.
    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.08 {
            score -= 10.0 * (1.0 - (k - k.round()).abs() / 0.08) * (1.1 - 0.5 * progress);
        }
    }

    // MUTATION (gen 29): big-item veto for fresh bins — opening a new bin for
    // a large item when a small-gap bin exists strands the large gap; instead
    // reward placing large items into the emptiest fitting bin.
    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 30, continuation): residual-variance dampener — prefer the
    // placement whose post-residual lands closest to the fleet mean residual,
    // shrinking the spread of open-bin gaps and improving future chain-fits.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 30, continuation): two-item exact-chain veto refinement —
    // when item + next exactly consumes the residual, escalate the reward late
    // in the stream where consolidation matters most.
    if next_item_size > 0 && post_residual == 0 && bin_residual != bin_capacity {
        if item_size as f64 >= mean_residual {
            score -= 10.0 * progress;
        }
    }

    // MUTATION (gen 30, continuation): mid-gap usability band tightening —
    // gaps in the 25–45 range are the primary source of wasted capacity when
    // next items are small; penalize proportionally to how far above the next
    // item they sit, but only when other bins remain available.
    if post_residual > 24 && post_residual < 45 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.55 * excess * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 31): mean-residual band anchoring — post-residuals that sit
    // within a narrow band around the fleet mean are the most likely to absorb
    // the next item; give an escalating reward as the band tightens late.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let band = (mean_residual * 0.15).max(2.0);
        let dev = (pr - mean_residual).abs();
        if dev <= band {
            score -= 6.0 * (1.0 - dev / band) * (0.5 + 0.8 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin last-resort gate refinement — only open a
    // new bin when every existing fit would strand a gap larger than the
    // expected future demand; otherwise the fresh-bin penalty must dominate.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress <= 0.85 {
        let expected_demand = mean_residual.max(next_item_size as f64).max(1.0);
        let min_strand = if post_residual > 0 && post_residual < expected_demand {
            expected_demand - post_residual as f64
        } else {
            0.0
        };
        if min_strand < expected_demand * 0.3 {
            score += 12.0 * (1.0 - min_strand / (expected_demand * 0.3)) * (1.0 - progress);
        }
    }

    // MUTATION (gen 31): chain-depth lookahead — reward placements whose
    // post-residual can absorb BOTH the next item and a mean-sized follow-up,
    // effectively planning a two-item continuation of the gap.
    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(2.0);
        if pr >= n + follow {
            score -= 8.0 * ((pr - n - follow) / cap_f).min(0.3) * 10.0 * (0.8 + 0.4 * progress);
        }
    }

    score
}

