        if unusable {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 31): variance-shrinking pair alignment — when the next
    // item's size matches the current bin's residual (a guaranteed perfect
    // fill next step), reward proportionally to how much this collapses the
    // fleet's residual spread, stronger late where consolidation pays.
    if next_item_size > 0 && bin_residual != bin_capacity && bin_residual - item_size == next_item_size {
        score -= 14.0 * (0.6 + 0.8 * progress);
    }

    score
}

