    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score += 12.0 * (1.0 - pr / mr) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 30): scarcity exact-fill escalation.
    if fitting_bins_count <= 2 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // MUTATION (gen 31, reinforced): fleet-mean targeting — steer post-residuals
    // toward the value most likely to be consumed by the incoming item stream.
    // When the post-residual sits within a tight band around the mean residual,
    // the next item (drawn near the mean) closes it; sharpen the reward band
    // and escalate it with progress since consolidation matters late.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let d = (pr - mr).abs();
        if d <= 2.0 {
            score -= 16.0 * (1.0 - d / 2.0) * (0.7 + 0.7 * progress);
        }
    }

    // MUTATION (gen 31): quantized-fill anticipation — when the post-residual
    // can host exactly two more mean-sized items, reward the placement so the
    // bin closes in a predictable chain rather than stranding a half-gap.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k2 = pr / mr;
        if k2 >= 2.0 && (k2 - 2.0).abs() < 0.1 {
            score -= 12.0 * (1.0 - (k2 - 2.0).abs() / 0.1) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin opening veto sharpening — opening a new bin
    // should be reserved for items that no open bin can host at reasonable
    // quality; when other fitting bins exist, push the fresh-bin score up
