        let stranded = mean_residual.max(0.0);
        score += (stranded / cap_f).min(0.5) * 40.0 * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 31): small-item gap-sweeper — tiny items (<= 15) are the
    // natural consumers of stranded sub-mean gaps; reward routing them into
