    if item_size <= 15 && bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 10.0 * (1.0 - pr / mr) * (0.6 + 0.6 * progress);
        }
    }

    score
}

