    // remain divisible by the mean residual, enabling future multi-item fills.
    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        if pr >= 2.0 * mr {
            let k = pr / mr;
            let frac_err = (k - k.round()).abs();
            if frac_err < 0.12 && k.round() >= 2.0 {
