    // bin when the item would leave a post residual usable by the next item,
    // or when no open bin fits well (large leftover risk otherwise).
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post > 0 && fresh_post < next_item_size as f64
            && (fresh_post - mean_residual).abs() > 3.0 {
            score += 18.0 * (1.0 - fresh_post / next_item_size as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 30): late-stream conservation — near the end, prefer
    // tightest possible fills strongly since no lookahead horizon remains.
    if progress > 0.75 && post_residual > 0 {
        let pr = post_residual as f64;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            score += 0.35 * after * (progress - 0.75) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
