        let fresh_post = cap_f - item_size as f64;
        let demand = next_item_size.max(mean_residual as u32) as f64;
        if fresh_post < demand {
            score += 14.0 * (1.0 - fresh_post / demand.max(1.0)) * (0.8 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        // Fresh-bin pair-fit chain — open a fresh bin when the
        // item + next pair fits cleanly, giving the next item an exact fit.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space with a sharper gradient.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast — residual is only valuable if future items can use it.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // MUTATION (gen 5): exact-chain bonus — when placing here lets the next
    // item perfectly consume the leftover, lock in the pair with a strong
    // reward scaled by scarcity of fitting bins.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (fitting_bins_count.min(5) as f64 / 5.0);
    }

    // MUTATION (gen 5): new-bin gate — only open a fresh bin when the item
    // is large or the stream is late; early small items should consolidate.
    if bin_residual == bin_capacity {
        let small_early = item_size <= bin_capacity / 4 && progress < 0.5;
        if small_early {
            score += 30.0;
        }
        // Fresh bin is attractive if the next item would exactly fill it too.
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 5): waste-threshold hardening — residuals below the
    // minimum plausible item size are pure loss; escalate the penalty
    // with stream progress since late waste is more costly.
    if post_residual > 0 && post_residual < 6 {
        score += 90.0 * (1.0 - post_residual as f64 / 6.0) * (0.7 + progress);
    }

    // MUTATION (gen 31): fine-grained near-exact pair fit — combine residual
    // fitting with lookahead anticipation. Reward bins whose post-residual is
    // within a tight window of the next item, scaled by how close it is.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        if diff <= 3.0 {
            score -= 20.0 * (1.0 - diff / 3.0) * (0.8 + 0.4 * progress);
        } else if diff <= 8.0 {
            score -= 7.0 * (1.0 - diff / 8.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 31): dead-space ratio minimizer — penalize slivers that no
    // plausible future item (next or mean-sized) can consume.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let usable = next_item_size as f64 > 0.0 && pr >= next_item_size as f64;
        if !usable {
            let mr = mean_residual.max(2.0);
            let dead = pr.min(mr);
            score += 6.0 * (dead / mr).min(1.0) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 31): fill-ratio refinement — reward placements whose
    // post-residual aligns with typical next-item magnitudes.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        if after <= 10.0 {
            score -= 13.0 * (1.0 - after / 10.0) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin waste guard — open a new bin only when the
    // item leaves enough room for the next item or the stream's typical item.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 1 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 24.0 * (1.0 - fresh_post / next_item_size as f64) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 31): late-stream consolidation — prefer bins that will be
    // near-full as the stream ends, reducing leftover fragmentation.
    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 31): near-full gap closer — small gaps between residual and
    // item signal a nearly perfect fit; reward them to tighten compaction.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    score
}

