    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // gen 24/26 mutations retained.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    // gen 28 mutations retained.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let follow = mean_residual.max(3.0).min(50.0);
        if after >= follow {
            score -= 10.0 * (1.0 - (after - follow) / cap_f) * (1.2 - 0.6 * progress);
        }
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mr = mean_residual.max(1.0);
        if (post_residual as f64) < mr * 0.5 && fitting_bins_count > 1 {
            score += 9.0 * (1.0 - post_residual as f64 / (mr * 0.5)) * (0.6 + 0.6 * progress);
        }
    }
    if post_residual >= 1 && post_residual <= 5 {
        score -= 8.0 * (6.0 - post_residual as f64) * (0.5 + progress);
    }

    // gen 29 mutations retained.
    if post_residual > 0 && bin_residual != bin_capacity {
        let avg_fill = (cap_f - mean_residual).max(0.0);
        let this_fill = item_size as f64 / bin_residual as f64;
        let target = (avg_fill / cap_f).clamp(0.2, 0.95);
        if this_fill >= target {
            score -= 14.0 * (this_fill - target).min(0.4) * (0.8 + 0.6 * progress);
        } else {
            score += 7.0 * (target - this_fill) * (1.0 - 0.4 * progress);
        }
    }

    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.08 {
            score -= 10.0 * (1.0 - (k - k.round()).abs() / 0.08) * (1.1 - 0.5 * progress);
        }
    }

    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 24 && post_residual < 45 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.55 * excess * (0.4 + 0.6 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if (pr - (n + mr)).abs() <= 2.0 {
            score -= 15.0 * (1.0 - (pr - (n + mr)).abs() / 2.0) * (1.0 - 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score += 12.0 * (1.0 - pr / mr) * (0.5 + 0.5 * progress);
        }
    }

    if fitting_bins_count <= 2 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // gen 30 mutations retained.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = 1.0 - post_residual as f64 / next_item_size as f64;
        score += 16.0 * dead * dead * (0.7 + 0.5 * progress);
        if fitting_bins_count <= 2 {
            score += 10.0 * dead * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        if pr >= 2.0 * mr {
            let k = pr / mr;
            let frac_err = (k - k.round()).abs();
            if frac_err < 0.12 && k.round() >= 2.0 {
                score -= 8.0 * (1.0 - frac_err / 0.12) * ((k.round() as f64).min(4.0) / 4.0) * (0.9 - 0.4 * progress);
            }
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post > 0 && fresh_post < next_item_size as f64
            && (fresh_post - mean_residual).abs() > 3.0 {
            score += 18.0 * (1.0 - fresh_post / next_item_size as f64) * (0.8 + 0.4 * progress);
        }
    }

    if progress > 0.75 && post_residual > 0 {
        let pr = post_residual as f64;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            score += 0.35 * after * (progress - 0.75) / 0.25;
        }
    }

    // MUTATION (gen 31): two-item lookahead compaction — when the item exactly
    // closes a bin (post_residual == 0), reward it more strongly late in the
    // stream and when other bins are plentiful, since perfect closure frees
    // the tightest bins from carrying dead slivers.
    if post_residual == 0 && bin_residual != bin_capacity {
        let closure_bonus = 30.0 * (0.5 + 0.8 * progress) * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 20.0)));
        score -= closure_bonus;
    }

    // MUTATION (gen 31): exact-fit pair anticipation — reward placements whose
    // post residual equals the next item plus a small mean-sized companion,
    // enabling a clean two-item finish and reducing stranded slivers.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr > n && (pr - n - mr).abs() <= 4.0 {
            score -= 14.0 * (1.0 - (pr - n - mr).abs() / 4.0) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin scarcity veto — with several fitting bins
    // available and small current item, opening a new bin is almost always
    // wasteful; penalize the new-bin candidate proportionally to how many
    // alternatives exist and how well they could absorb the item.
    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let alt = fitting_bins_count as f64;
        score += 10.0 * alt.ln() * (1.0 - 0.4 * progress);
        if item_size as f64 <= cap_f * 0.3 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 31): near-exact residual sharpening — when the post
    // residual is within 2 of the next item, treat it as a near-perfect fit
    // and reward it strongly, tightening compaction at fine granularity.
    if post_residual > 0 && next_item_size > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near > 0 && near <= 2 {
            score -= 20.0 * (1.0 - near as f64 / 3.0) * (0.6 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0 + 30.0 * (10 - post_residual) as f64 * (0.7 + 0.6 * progress);
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let gap = bin_residual.saturating_sub(item_size);
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(1.0);
        let hostable = pr >= n || pr >= mr;
        let stranded = n > 0.0 && pr < n && pr > n * 0.5 && pr < mr;
        if hostable {
            score -= 8.0 * (pr / cap_f).min(0.3) * 10.0 * (0.6 + 0.4 * progress);
        } else if stranded {
            score += 12.0 * (0.5 + progress);
        }
    }

    if next_item_size > 0 && bin_residual != bin_capacity {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0 && pr < n * 0.25 && n > cap_f * 0.35 {
            score -= 16.0 * (1.0 - pr / (n * 0.25)) * (0.5 + progress);
        } else if pr > cap_f * 0.4 && n < cap_f * 0.15 {
            score += 7.0 * (1.0 - progress);
        }
    }

    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 4.0 * progress;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }

    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 34.0 * g * (1.0 - g) * (0.7 + progress);
    }

    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }

    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n {
            let after = pr - n;
            score -= 10.0 * (1.0 - after / pr) * (0.6 + 0.4 * progress);
        } else {
            let deficit = (n - pr) / n;
            if deficit < 0.3 {
                score += 22.0 * (1.0 - deficit / 0.3) * (0.5 + 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after <= 6 {
            score -= 20.0 * (1.0 - after as f64 / 7.0) * (0.6 + 0.6 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.4 {
            score += 18.0 * (1.0 - progress);
        }
        if fitting_bins_count <= 2 {
            score += 12.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual >= 20 && post_residual <= 35 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr < n {
            score += 9.0 * (1.0 - pr / n) * (0.6 + 0.4 * progress);
        } else if pr - n <= 10.0 {
            score -= 6.0 * (1.0 - (pr - n) / 11.0) * (0.6 + 0.4 * progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let usable = next_item_size as f64 > 0.0 && pr >= next_item_size as f64;
        if !usable {
            let mr = mean_residual.max(2.0);
            let dead = pr.min(mr);
            score += 5.0 * (dead / mr).min(1.0) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        if after <= 10.0 {
            score -= 13.0 * (1.0 - after / 10.0) * (0.8 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 1 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 24.0 * (1.0 - fresh_post / next_item_size as f64) * (1.0 - 0.3 * progress);
        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        let tightest_bonus = 10.0 * (1.0 - 1.0 / fitting_bins_count as f64);
        score += tightest_bonus * (0.6 + 0.4 * progress);
    }

    if post_residual > 0 && next_item_size > 1 && post_residual > next_item_size {
        let k = post_residual as f64 / next_item_size as f64;
        if k < 4.0 && (k - k.round()).abs() < 0.02 {
            score -= 14.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): two-step chain compaction — when the post-residual can
    // host the next item AND the leftover after that still matches the stream's
    // typical demand, reward the double fill strongly.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if after >= mr * 0.5 && after <= mr * 1.5 {
            score -= 12.0 * (1.0 - (after - mr * 0.5) / mr) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin acceptance gate — only allow a new bin when the
    // item is large relative to capacity or no existing bin fits well; otherwise
    // penalize opening fresh capacity to force consolidation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let big_item = item_size as f64 > cap_f * 0.45;
        let poor_fits = next_item_size > 0
            && (bin_capacity.saturating_sub(item_size)) < next_item_size;
        if !(big_item || poor_fits || progress > 0.9) {
            score += 26.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): exact residual match escalation — sharpen the reward for
    // bins whose post-residual exactly equals the next item, weighted by scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score -= 30.0 * (1.0 + scarcity) * (0.6 + 0.4 * progress);
    }

    // MUTATION (gen 31): residual-variance-aware smoothing — when residuals are
    // highly dispersed, prefer bins closest to the mean residual to recompact.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 3.0 {
            score -= 11.0 * (1.0 - dev / 3.0) * (0.7 + 0.4 * progress);
        } else if dev > 15.0 && pr > mean_residual {
            score += 5.0 * ((dev - 15.0) / cap_f).min(0.12) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
