        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    // gen 31 mutations retained.
    if post_residual == 0 && bin_residual != bin_capacity {
        let closure_bonus = 30.0 * (0.5 + 0.8 * progress) * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 20.0)));
        score -= closure_bonus;
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr > n && (pr - n - mr).abs() <= 4.0 {
            score -= 14.0 * (1.0 - (pr - n - mr).abs() / 4.0) * (0.7 + 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let alt = fitting_bins_count as f64;
        score += 10.0 * alt.ln() * (1.0 - 0.4 * progress);
        if item_size as f64 <= cap_f * 0.3 {
            score += 8.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near > 0 && near <= 2 {
            score -= 20.0 * (1.0 - near as f64 / 3.0) * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 32): dead-space kill zone — when the post residual is smaller
    // than any plausible future item (next and mean), the leftover is dead weight.
    // Penalize proportionally to the dead fraction, but only when alternative
    // bins exist so we don't force overflow of the only fitting bin.
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let n = if next_item_size > 0 { next_item_size as f64 } else { f64::INFINITY };
        let mr = mean_residual.max(2.0);
        if pr < n.min(mr) {
            let dead_frac = 1.0 - pr / n.min(mr);
            score += 22.0 * dead_frac * dead_frac * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 32): two-step lookahead compaction — reward placements whose
    // post residual can absorb the next item AND still leave room for a
    // mean-sized item after it, enabling chained fills that squeeze bins tighter.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n + mr {
            let chain_slack = pr - n - mr;
            score -= 12.0 * (1.0 - (chain_slack / cap_f).min(1.0)) * (0.8 - 0.3 * progress);
        }
    }

    // MUTATION (gen 32): fresh-bin last-resort gate — only allow the new-bin
    // candidate to win when the current item is large (would strand big slivers
    // elsewhere) or when no open bin fits; otherwise push the fresh bin score up.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap_f;
        if fitting_bins_count > 0 && item_frac < 0.5 {
            score += 18.0 * (0.5 - item_frac) * 2.0 * (0.7 + 0.5 * progress);
        }
        if next_item_size > 0 && (cap_f - item_size as f64) >= next_item_size as f64 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 32): residual-harmonic reward — bins whose post residual is a
    // small divisor-like chunk (1..=6) are prime targets for later slivers;
    // reward them increasingly toward the stream end when consolidation matters.
    if post_residual >= 1 && post_residual <= 6 && bin_residual != bin_capacity {
        score -= 10.0 * (7.0 - post_residual as f64) * 0.25 * (0.5 + progress);
    }

    score
}

