    }
    if post_residual >= 1 && post_residual <= 5 {
        score -= 8.0 * (6.0 - post_residual as f64) * (0.5 + progress);
    }

    // gen 29 mutations retained.
    if post_residual > 0 && bin_residual != bin_capacity {
        let avg_fill = (cap_f - mean_residual).max(0.0);
        let this_fill = item_size as f64 / bin_residual as f64;
        let target = (avg_fill / cap_f).clamp(0.2, 0.95);
        if this_fill >= target {
            score -= 14.0 * (this_fill - target).min(0.4) * (0.8 + 0.6 * progress);
        } else {
            score += 7.0 * (target - this_fill) * (1.0 - 0.4 * progress);
        }
    }

    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.08 {
            score -= 10.0 * (1.0 - (k - k.round()).abs() / 0.08) * (1.1 - 0.5 * progress);
        }
    }

    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 24 && post_residual < 45 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.55 * excess * (0.4 + 0.6 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if (pr - (n + mr)).abs() <= 2.0 {
            score -= 15.0 * (1.0 - (pr - (n + mr)).abs() / 2.0) * (1.0 - 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score += 12.0 * (1.0 - pr / mr) * (0.5 + 0.5 * progress);
        }
    }

    if fitting_bins_count <= 2 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // gen 30 mutations retained.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let usable = next_item_size as f64 > 0.0 && pr >= next_item_size as f64;
        if !usable {
            let mr = mean_residual.max(2.0);
            let dead = pr.min(mr);
            score += 5.0 * (dead / mr).min(1.0) * (0.7 + 0.5 * progress);
        }
    }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        if after <= 10.0 {
            score -= 13.0 * (1.0 - after / 10.0) * (0.8 + 0.4 * progress);
        }
    }
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 1 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 24.0 * (1.0 - fresh_post / next_item_size as f64) * (1.0 - 0.3 * progress);
        }
    }
    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 32): exact-fit chain anticipation — when the current
    // placement leaves a residual that the NEXT item would fill exactly,
    // escalate the reward as open-bin scarcity grows, coupling lookahead
    // with consolidation pressure.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score -= 40.0 * scarcity * (0.6 + 0.6 * progress);
    }

    // MUTATION (gen 32): dead-gap divisibility cascade — residual that can
    // be split into two next-item-sized chunks (k*n or k*n + tiny remainder)
    // is high-utility; reward it to keep future placements exact.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr > n {
            let k = (pr / n).floor();
            let rem = pr - k * n;
            if k >= 2.0 && rem <= 4.0 {
                score -= 14.0 * (1.0 - rem / 5.0) * (0.6 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 32): fresh-bin two-item fill test — open a new bin only
    // if item + next nearly fills it (high fill ratio); otherwise prefer
    // consolidating into open bins to reduce total bins.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if pair <= cap_f {
            let fill = pair / cap_f;
            if fill < 0.6 {
                score += 26.0 * (0.6 - fill) * (0.8 + 0.4 * progress);
            } else if fill >= 0.9 {
                score -= 30.0 * (fill - 0.9) * 10.0 * (0.6 + 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 32): residual-mean harmony gate — when the post-residual
    // matches the mean open-bin residual closely, the leftover stays usable
    // by typical future items; reward this alignment more strongly late.
    if post_residual > 0 && bin_residual != bin_capacity && open_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let rel = (pr - mr).abs() / mr;
        if rel <= 0.15 {
            score -= 11.0 * (1.0 - rel / 0.15) * (0.5 + 0.7 * progress);
        }
    }

    // MUTATION (gen 32): scarcity consolidation gate — with very few fitting
    // bins and a non-empty residual, deepen the preference for tight fits so
    // the item lands where waste is minimal rather than opening a bin.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        score -= 20.0 * (1.0 - frac * 4.0).max(0.0) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
