    // MUTATION (gen 5): waste-threshold hardening.
    if post_residual > 0 && post_residual < 6 {
        score += 90.0 * (1.0 - post_residual as f64 / 6.0) * (0.7 + progress);
    }

    // MUTATION (gen 33): residual-entropy scaling — steep penalty for near-miss
    // residuals just below the next item, scaled by remaining stream length.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    // MUTATION (gen 33): harvestable-residual matching — reward post-residuals
    // close to the mean residual, the most likely future gap to fill.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
