    }

    // MUTATION (gen 34): late-stream consolidation — as the stream ends,
    // aggressively prefer closing bins tight and avoid opening new ones.
    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 35): exact-gap harvest — when the residual equals a small
    // exact gap (1..=6), treat it as fully closed; deepen reward with progress.
    if post_residual >= 1 && post_residual <= 6 {
        score -= 20.0 * (7.0 - post_residual as f64) / 6.0 * (0.6 + 0.6 * progress);
    }

    // MUTATION (gen 35): triple-chain lookahead — reward residuals that can host
    // the next item AND still leave room for a mean-sized follow-up item.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n + mr {
            let triple_gap = pr - n - mr;
            if triple_gap <= 4.0 {
                score -= 16.0 * (1.0 - triple_gap / 4.0) * (0.8 + 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 35): fresh-bin pair-completion gate — open a new bin when the
    // item exactly pairs with the next item to fill capacity; otherwise resist
    // opening bins whose post-residual cannot even host the next item.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        if (fresh_post as u32) == next_item_size {
            score -= 55.0 * (0.6 + 0.6 * progress);
        } else if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 35): divisibility bonus — residuals that are integer multiples
    // of the mean residual are statistically reusable; reward near-multiples.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.06 {
            score -= 12.0 * (1.0 - (k - k.round()).abs() / 0.06) * (1.0 - 0.5 * progress);
        }
    }

    score
}

