            score -= 15.0 * (1.0 - gap as f64 / 4.0) * (0.5 + 0.7 * stream_left);
        }
    }
    if post_residual > 0 && bin_residual != bin_capacity && progress > 0.25 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr) / mr;
        if dev > 0.6 {
            score += 6.0 * (dev - 0.6).min(1.5) * ((progress - 0.25) / 0.75);
        }
    }
    if bin_residual == bin_capacity && item_size as f64 > cap_f * 0.4 && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post >= next_item_size as f64 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + 0.4 * progress);
        }
    }
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let scarcity = (4 - fitting_bins_count.min(4)) as f64 / 4.0;
        score -= 22.0 * scarcity * (0.6 + 0.6 * progress);
    }

    // MUTATION (gen 35): dead-space parity sharpening — residuals unusable by the next
    // item are penalized proportionally to how far they sit below the next harvestable
    // size, escalating as the stream depletes; directly attacks dead-space waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 9.0 * (gap / n) * (0.6 + 1.2 * stream_left);
    }

    // MUTATION (gen 35): harvest-chain density — reward residuals that absorb the next
    // item and then land within a tight window of the mean residual (a second future
    // fit), weighted strongest early when many items remain to exploit the chain.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 4.0 {
                score -= 15.0 * (1.0 - d / 4.0) * (1.1 - 0.6 * progress);
            }
        }
    }

    // MUTATION (gen 35): fresh-bin dead-space veto — a fresh bin whose post-residual is
    // unusable by the next item is penalized so existing bins win; a fresh residual
    // exactly matching the next item is a strong opening signal and gets rewarded.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post < n {
            score += 18.0 * (1.0 - fresh_post / n) * (0.7 + 0.7 * progress);
        } else if (fresh_post - n).abs() <= 1.0 {
            score -= 20.0 * (1.0 - 0.5 * progress);
        } else if fresh_post > mr * 1.8 {
            score += 6.0 * ((fresh_post - mr * 1.8) / cap_f).min(0.25) * 8.0 * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 35): fragment-aware convex cost — when the mean residual suggests
    // many small leftover fragments, prefer minimal post-residuals harder via a
    // convex scaling term that fades as the stream ends.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let fragility = (mr / cap_f).clamp(0.02, 0.5);
        score += pr * fragility * 0.35 * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 35): scarcity-weighted perfect closure — when the post residual
    // exactly matches the next item and few bins compete, lock the win harder late in
    // the stream where deterministic closures matter most for the final bin count.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
        score -= 18.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
