    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space with a sharper gradient.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Residual quantization reward.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr > n {
            let k = (pr / n).floor();
            let rem = pr - k * n;
            if rem < 3.0 && k >= 1.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress);
            }
            if (pr - k * n) < 1.0 {
                score += 5.0 * progress;
            }
        }
    }

    // Dual-size chain check.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let chain = next_item_size as f64 + mean_residual.max(1.0);
        if pr >= chain {
            score -= 9.0 * (1.0 - (pr - chain) / cap_f).min(1.0) * (0.6 + progress);
        }
    }

    // New-bin suppression under consolidation.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 1 {
        score += 12.0 * (open_bins_count as f64).ln() * (1.0 - progress);
        if next_item_size as f64 > cap_f * 0.5 {
            score -= 20.0;
        }
    }

    // MUTATION (gen 14): tight-fit precision band.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 14): perfect-pair lookahead.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 14): fresh-bin waste guard.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // MUTATION (gen 14): residual utility ratio.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 14): late-stream consolidation gate.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 43): residual-depth multi-harvest ledger — residuals that can
    // absorb the next item AND leave room for another typical item are high-yield
    // sinks; residuals that cannot fit the next item at all are dead space whose
    // cost grows with stream depletion.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        if pr < n {
            score += 8.0 * (1.0 - pr / n) * (0.8 + 1.4 * stream_left);
        } else {
            let after = pr - n;
            let mr = mean_residual.max(2.0);
            if after >= mr * 0.5 && after <= mr * 1.8 {
                score -= 11.0 * (1.0 - ((after - mr) / mr).abs().min(1.0)) * (0.6 + 0.8 * stream_left);
            }
        }
    }

    // MUTATION (gen 43): tight-closure sweep — near-zero post-residuals rewarded
    // progressively harder as the stream depletes, since tiny fragments can never
    // be recovered later.
    if post_residual > 0 && post_residual <= 6 {
        let tail = 1.0 - progress;
        score -= (7.0 - post_residual as f64) * (1.0 + 1.5 * tail);
    }

    // MUTATION (gen 43): fresh-bin harvest gate — a new bin should open only when
    // its post-residual is either immediately harvestable (within a small margin
    // of the next item) or large enough to serve multiple future items; otherwise
    // the existing bins with tighter fits win.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post < n {
            score += 16.0 * (1.0 - fresh_post / n) * (0.6 + 0.7 * progress);
        } else if (fresh_post - n) <= 2.0 {
            score -= 14.0 * (1.0 - (fresh_post - n) / 3.0) * (0.7 + 0.5 * progress);
        } else if fresh_post > mr * 1.7 {
            score += 9.0 * ((fresh_post / (mr * 1.7)) - 1.0).min(1.0) * (0.5 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): competition-aware best-fit sharpening — with many bins
    // competing, only genuinely tight fits should win; with a single fitting bin,
    // accept it more readily to avoid opening fresh bins.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let comp = (fitting_bins_count as f64).max(1.0);
        let crowd = 1.0 / (1.0 + (comp.ln() * 0.6));
        score += pr * 0.12 * crowd * (0.6 + 0.6 * progress);
        if fitting_bins_count == 1 {
            score -= 9.0 * (1.0 - pr / cap_f) * (0.8 + 0.4 * progress);
        }
    }

    // MUTATION (gen 43): late-stream orphan sweep — dead residuals late in the
    // stream are stranded capacity; penalize proportionally to how unusable
    // they are for the next item.
    if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let tail = (progress - 0.75) / 0.25;
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        score += 14.0 * tail * (1.0 - pr / n) * (0.6 + 0.6 * tail);
    }

    score
}

