        let usable_depth = (after / mr).min(2.0);
        score -= 5.0 * usable_depth * (0.5 + 0.7 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // retained mutations.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let follow = mean_residual.max(3.0).min(50.0);
        if after >= follow {
            score -= 10.0 * (1.0 - (after - follow) / cap_f) * (1.2 - 0.6 * progress);
        }
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mr = mean_residual.max(1.0);
        if (post_residual as f64) < mr * 0.5 && fitting_bins_count > 1 {
            score += 9.0 * (1.0 - post_residual as f64 / (mr * 0.5)) * (0.6 + 0.6 * progress);
        }
    }
    if post_residual >= 1 && post_residual <= 5 {
        score -= 8.0 * (6.0 - post_residual as f64) * (0.5 + progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let avg_fill = (cap_f - mean_residual).max(0.0);
        let this_fill = item_size as f64 / bin_residual as f64;
        let target = (avg_fill / cap_f).clamp(0.2, 0.95);
        if this_fill >= target {
            score -= 14.0 * (this_fill - target).min(0.4) * (0.8 + 0.6 * progress);
        } else {
            score += 7.0 * (target - this_fill) * (1.0 - 0.4 * progress);
        }
    }

    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.08 {
            score -= 10.0 * (1.0 - (k - k.round()).abs() / 0.08) * (1.1 - 0.5 * progress);
        }
    }

    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 24 && post_residual < 45 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.55 * excess * (0.4 + 0.6 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if (pr - (n + mr)).abs() <= 2.0 {
            score -= 15.0 * (1.0 - (pr - (n + mr)).abs() / 2.0) * (1.0 - 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score += 12.0 * (1.0 - pr / mr) * (0.5 + 0.5 * progress);
        }
    }

    if fitting_bins_count <= 2 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let usable = next_item_size as f64 > 0.0 && pr >= next_item_size as f64;
        if !usable {
            let mr = mean_residual.max(2.0);
            let dead = pr.min(mr);
            score += 5.0 * (dead / mr).min(1.0) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        if after <= 10.0 {
            score -= 13.0 * (1.0 - after / 10.0) * (0.8 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 1 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 24.0 * (1.0 - fresh_post / next_item_size as f64) * (1.0 - 0.3 * progress);
        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let fits_next = n > 0.0 && pr >= n;
        let fits_mean = pr >= mr;
        if !fits_next && !fits_mean {
            let waste = pr / cap_f;
            let stream_left = 1.0 - progress;
            score += (9.0 + 10.0 * stream_left) * (0.5 + waste).min(1.0);
        } else if !fits_next {
            score += 3.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let chain_gap = (after - mr).abs();
            if chain_gap <= 3.0 {
                score -= 11.0 * (1.0 - chain_gap / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    if post_residual >= 1 && post_residual <= 2 && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - post_residual as f64 / 3.0) * (0.8 + 0.4 * progress);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let fresh_post = cap_f - item_size as f64;
        let loose_elsewhere = mean_residual.max(2.0);
        if fresh_post < loose_elsewhere * 0.8 && progress > 0.3 {
            score -= 14.0 * (1.0 - fresh_post / (loose_elsewhere * 0.8)) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
        if d <= win {
            score -= 14.0 * (1.0 - d / win) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 18.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0).min(3.0);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(1.0);
        if fresh_post < mr {
            score += 16.0 * (1.0 - fresh_post / mr) * (0.6 + 0.6 * progress);
        } else if fresh_post > mr * 1.6 && progress < 0.6 {
            score -= 10.0 * ((fresh_post - mr * 1.6) / cap_f).min(0.2) * 10.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr < n && pr < mr {
            let stream_left = 1.0 - progress;
            score += 6.0 * (pr / mr) * (pr / mr) * (0.8 + 0.8 * stream_left);
        }
    }

    // gen 34 retained: competition-aware best-fit sharpening.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let comp = (fitting_bins_count as f64).max(1.0);
        let crowd = 1.0 / (1.0 + (comp.ln() * 0.6));
        score += pr * 0.12 * crowd * (0.6 + 0.6 * progress);
        if fitting_bins_count == 1 {
            score -= 9.0 * (1.0 - pr / cap_f) * (0.8 + 0.4 * progress);
        }
    }

    // gen 34 retained: two-step harvest lookahead.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after >= mr * 0.8 && after <= mr * 1.4 {
                score -= 13.0 * (1.0 - (after - mr).abs() / (mr * 0.6)) * (0.5 + 0.7 * (1.0 - progress));
            }
        }
    }

    // gen 34 retained: late-stream exact-closure bias.
    if progress > 0.85 {
        let tail = (progress - 0.85) / 0.15;
        if post_residual == 0 {
            score -= 14.0 * tail;
        } else if post_residual <= 4 {
            score -= 10.0 * tail * (1.0 - post_residual as f64 / 5.0);
        } else {
            score += 8.0 * tail * ((post_residual as f64 / cap_f).min(0.3));
        }
    }

    // gen 34 retained: fresh-bin residual-quality gate.
    if bin_residual == bin_capacity && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = fresh_post / mr;
        let frac = (k - k.round()).abs();
        if frac > 0.25 && progress > 0.25 {
            score += 11.0 * (frac - 0.25).min(0.5) * (0.6 + 0.6 * progress);
        } else if frac <= 0.1 && progress < 0.7 {
            score -= 7.0 * (1.0 - frac / 0.1) * (1.0 - progress);
        }
    }

    // gen 35 retained: dead-space parity sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 9.0 * (gap / n) * (0.6 + 1.2 * stream_left);
    }

    // gen 35 retained: harvest-chain density.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 4.0 {
                score -= 15.0 * (1.0 - d / 4.0) * (1.1 - 0.6 * progress);
            }
        }
    }

    // gen 35 retained: fresh-bin dead-space veto.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post < n {
            score += 18.0 * (1.0 - fresh_post / n) * (0.7 + 0.7 * progress);
        } else if (fresh_post - n).abs() <= 1.0 {
            score -= 20.0 * (1.0 - 0.5 * progress);
        } else if fresh_post > mr * 1.8 {
            score += 6.0 * ((fresh_post - mr * 1.8) / cap_f).min(0.25) * 8.0 * (0.4 + 0.6 * progress);
        }
    }

    // gen 35 retained: residual-variance-aware fit scaling.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let fragility = (mr / cap_f).clamp(0.02, 0.5);
        score += pr * fragility * 0.35 * (1.0 - 0.4 * progress);
    }

    // gen 36: dead-space parity sharpening continued.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        if pr < n {
            let gap = n - pr;
            score += 4.0 * (gap * gap) / n * (0.7 + 1.0 * stream_left);
        } else {
            let margin = pr - n;
            if margin <= 2.0 {
                score -= 6.0 * (1.0 - margin / 3.0) * (0.5 + 0.7 * stream_left);
            }
        }
    }

    // gen 36: residual ladder alignment.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round().max(1.0);
        let dev = (pr - k * mr).abs() / mr;
        if dev <= 0.12 && k <= 3.0 {
            score -= 8.0 * (1.0 - dev / 0.12) * (1.0 - 0.5 * progress) * (1.0 / k.sqrt());
        }
    }

    // gen 36: fresh-bin last-resort calibration.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let suppress = ((fitting_bins_count as f64) / 3.0).min(1.0);
        score += 10.0 * suppress * (0.4 + 0.6 * progress);
        if post_residual > 0 && next_item_size > 0 {
            let fresh_post = cap_f - item_size as f64;
            let n = next_item_size as f64;
            if fresh_post >= n && (fresh_post - n) <= 3.0 {
                score -= 9.0 * (1.0 - (fresh_post - n) / 4.0) * (0.6 + 0.5 * progress);
            }
        }
    }

    // gen 37: dead-space parity cubic term.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let dead_frac = 1.0 - pr / n;
        score += 5.0 * dead_frac * dead_frac * dead_frac * (n / cap_f).max(0.1) * (0.6 + 1.4 * stream_left);
    }

    // gen 37: next-item multiple alignment.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round().max(1.0);
        let dev = (pr - k * n).abs() / n;
        if dev <= 0.08 && k >= 2.0 && k <= 3.0 {
            score -= 7.0 * (1.0 - dev / 0.08) * (1.0 - 0.6 * progress) * (1.0 / (k - 1.0).sqrt());
        }
    }

    // gen 37: fresh-bin calibration refinement.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post > mr * 1.5 && progress > 0.4 {
            score += 6.0 * ((fresh_post / (mr * 1.5)) - 1.0).min(1.0) * (0.5 + 0.5 * progress);
        }
        if post_residual > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if fresh_post >= n && (fresh_post - n) <= 2.0 {
                score -= 5.0 * (1.0 - (fresh_post - n) / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    // gen 38: two-step dead-space lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && item_size + next_item_size <= bin_capacity && fitting_bins_count > 1 {
        let stream_left = 1.0 - progress;
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (gap / next_item_size as f64) * (0.5 + 1.5 * stream_left);
    }

    // gen 38: harvestable-residual depth bonus.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if after >= mr * 0.5 && after <= mr * 2.0 {
            let centering = 1.0 - ((after - mr) / mr).abs();
            score -= 9.0 * centering * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // gen 38: late-stream orphan sweep.
    if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let tail = (progress - 0.75) / 0.25;
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        score += 14.0 * tail * (1.0 - pr / n) * (0.6 + 0.6 * tail);
    }

    // gen 39: exact-fill competition tiebreak.
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round();
        if k >= 1.0 && k <= 4.0 {
            let dev = (pr - k * mr).abs();
            if dev <= 1.5 {
                score -= 6.0 * (1.0 - dev / 1.5) * (0.5 + 0.8 * (1.0 - progress)) / k.sqrt();
            }
        }
    }

    // gen 39: dead-space entropy gate.
    if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let unusable = 1.0 - pr / (n * 0.5);
        score += 7.0 * unusable * unusable * (0.7 + 0.9 * (1.0 - progress));
    }

    // gen 39: fresh-bin pair-closure veto refinement.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        if (fresh_post - n).abs() <= 0.5 && progress < 0.8 {
            score -= 16.0 * (1.0 - progress);
        } else if fresh_post < n * 0.5 && progress > 0.5 {
            score += 12.0 * (1.0 - fresh_post / (n * 0.5)) * (0.5 + 0.8 * progress);
        }
    }

    // gen 40: harvest-window sharpening.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 2.0 {
                score -= 12.0 * (1.0 - d / 2.0) * (0.6 + 0.9 * (1.0 - progress));
            }
        }
    }

    // gen 40: fresh-bin efficiency gate.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let harvestable = fresh_post >= mr * 1.1;
        if !harvestable {
            score += 10.0 * (1.0 - fresh_post / (mr * 1.1)) * (0.5 + 0.7 * progress);
        } else if fresh_post >= mr * 1.6 {
            score -= 7.0 * ((fresh_post / cap_f).min(0.4)) * (0.5 + 0.6 * (1.0 - progress));
        }
    }

    // gen 41: cumulative dead-space ledger.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let stranded_frac = 1.0 - pr / n;
        score += 6.0 * stranded_frac * stranded_frac * (0.8 + 1.0 * stream_left);
    }

    // gen 41: harvest-chain momentum.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after <= mr * 0.5 {
                score -= 8.0 * (1.0 - after / (mr * 0.5)) * (0.7 + 0.8 * progress);
            }
        }
    }

    // gen 41: fresh-bin threshold tightening.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(2.0) };
        if fresh_post < n * 0.6 {
            score += 15.0 * (1.0 - fresh_post / (n * 0.6)) * (0.6 + 0.6 * progress);
        }
    }

    // gen 42: multi-item capacity ledger.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).floor();
        let stream_left = 1.0 - progress;
        if k < 1.0 {
            score += 7.0 * (1.0 - pr / n) * (0.9 + 1.1 * stream_left);
        } else if k >= 2.0 {
            score -= 5.0 * (k.min(3.0) - 1.0) * (0.6 + 0.6 * (1.0 - progress));
        }
    }

    // gen 42: fresh-bin density veto.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        if fresh_post >= n {
            let excess = fresh_post - n;
            if excess > n && excess > mean_residual.max(2.0) {
                score += 8.0 * ((excess - n) / cap_f).min(0.3) * 10.0 * (0.5 + 0.7 * progress);
            }
        }
    }

    // gen 42: tight-closure sweep.
    if post_residual > 0 && post_residual <= 6 {
        let tail = (1.0 - progress).max(0.0);
        score -= (7.0 - post_residual as f64) * (1.2 + 1.3 * (1.0 - tail));
    }

    // gen 43 retained: perfect-fit ladder.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 1.0 && (pr - k * n).abs() < 0.5 {
            score -= 10.0 * (1.0 + 0.8 * (1.0 - progress)) / k.sqrt();
        }
    }

    // gen 43 retained: fresh-bin exact-closure gate.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let k = (fresh_post / n).round();
        if k < 1.0 || (fresh_post - k * n).abs() >= 2.0 {
            score += 9.0 * (1.0 - (fresh_post / (k.max(1.0) * n)).min(1.0)) * (0.5 + 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0) * (0.6 + 0.6 * progress);
        }
    }

    // gen 43 retained: late-stream residual compression.
    if progress > 0.8 && post_residual > 0 {
        let tail = (progress - 0.8) / 0.2;
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 5.0 * tail * (1.0 - pr / mr);
        } else {
            score += 4.0 * tail * ((pr - mr) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 44): harvest-depth ladder — when the post-residual can absorb
    // the next item AND the remainder stays harvestable by the mean residual, the
    // bin supports a multi-step chain; deepen the reward for longer chains (k>=2)
    // and sharpen the window as the stream depletes, attacking residual dead space
    // at the chain level rather than the single-step level.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let after = pr - n;
        let chain_k = (after / mr).floor();
        if chain_k >= 1.0 {
            let slack = after - chain_k * mr;
            let centered = 1.0 - (slack / mr).abs();
            score -= 11.0 * centered * (chain_k.min(3.0).sqrt()) * (0.7 + 0.9 * (1.0 - progress));
        }
    }

    // MUTATION (gen 44): fresh-bin chain-capacity gate — a new bin is worthwhile only
    // if its fresh post-residual supports at least as long a harvest chain as the
    // mean residual elsewhere; penalize short-chain fresh bins proportionally to the
    // chain deficit, with weight rising as fitting alternatives grow.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let fresh_chain = if fresh_post >= n { ((fresh_post - n) / mr).floor() } else { -1.0 };
        let alt_chain = 1.0;
        if fresh_chain < alt_chain {
            let deficit = (alt_chain - fresh_chain.max(0.0)) / alt_chain;
            score += 12.0 * deficit * (0.4 + 0.6 * (fitting_bins_count as f64).min(3.0) / 3.0) * (0.5 + 0.7 * progress);
        } else if fresh_chain >= 2.0 && progress < 0.6 {
            score -= 6.0 * (fresh_chain.min(3.0) - 1.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 44): mid-stream residual smoothing — between progress 0.35 and
    // 0.75, gently compress the score spread of mid-sized residuals (10..=40) so
    // chain-structure terms above dominate over raw residual magnitude, reducing
    // premature bin fragmentation in the long middle of the stream.
    if progress > 0.35 && progress < 0.75 && post_residual > 10 && post_residual < 40 {
        let mid = (progress - 0.35) / 0.4;
        let bell = (mid * (1.0 - mid) * 4.0).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr).abs() / mr;
        if dev <= 0.5 {
            score -= 6.0 * bell * (1.0 - dev / 0.5);
        } else {
            score += 4.0 * bell * (dev - 0.5).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space with a sharper gradient.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast — residual is only valuable if future items can use it.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // MUTATION (gen 5): exact-chain bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (fitting_bins_count.min(5) as f64 / 5.0);
    }

    // MUTATION (gen 5): new-bin gate.
    if bin_residual == bin_capacity {
        let small_early = item_size <= bin_capacity / 4 && progress < 0.5;
        if small_early {
            score += 30.0;
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 5): waste-threshold hardening.
    if post_residual > 0 && post_residual < 6 {
        score += 90.0 * (1.0 - post_residual as f64 / 6.0) * (0.7 + progress);
    }

    // MUTATION (gen 33): residual-entropy scaling.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    // MUTATION (gen 33): harvestable-residual matching.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
        if d <= win {
            score -= 14.0 * (1.0 - d / win) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 33): perfect-closure escalation.
    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 18.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0).min(3.0);
    }

    // MUTATION (gen 33): fresh-bin only-when-needed gate.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(1.0);
        if fresh_post < mr {
            score += 16.0 * (1.0 - fresh_post / mr) * (0.6 + 0.6 * progress);
        } else if fresh_post > mr * 1.6 && progress < 0.6 {
            score -= 10.0 * ((fresh_post - mr * 1.6) / cap_f).min(0.2) * 10.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 33): quadratic dead-space ramp.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr < n && pr < mr {
            let stream_left = 1.0 - progress;
            score += 6.0 * (pr / mr) * (pr / mr) * (0.8 + 0.8 * stream_left);
        }
    }

    // MUTATION (gen 34): near-exact pair chaining.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let chain_gap = (after - mr).abs();
            if chain_gap <= 3.0 {
                score -= 12.0 * (1.0 - chain_gap / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 34): dead-zone escalation.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let fits_next = n > 0.0 && pr >= n;
        let fits_mean = pr >= mr;
        if !fits_next && !fits_mean {
            let waste = pr / cap_f;
            let stream_left = 1.0 - progress;
            score += (9.0 + 10.0 * stream_left) * (0.5 + waste).min(1.0);
        } else if !fits_next {
            score += 3.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 34): sliver-exact matching.
    if post_residual >= 1 && post_residual <= 2 && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - post_residual as f64 / 3.0) * (0.8 + 0.4 * progress);
    }

    // MUTATION (gen 34): fresh-bin threshold refinement.
    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let fresh_post = cap_f - item_size as f64;
        let loose_elsewhere = mean_residual.max(2.0);
        if fresh_post < loose_elsewhere * 0.8 && progress > 0.3 {
            score -= 14.0 * (1.0 - fresh_post / (loose_elsewhere * 0.8)) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 34): late-stream consolidation.
    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 42): exact-chain escalation.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let stream_left = 1.0 - progress;
        score -= 18.0 * (0.5 + 1.0 * stream_left);
    }

    // MUTATION (gen 42): harvest-window tightening.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 1.5 {
                score -= 10.0 * (1.0 - d / 1.5) * (0.6 + 0.9 * (1.0 - progress));
            }
        }
    }

    // MUTATION (gen 42): fresh-bin double-harvest veto.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post >= n {
            let after = fresh_post - n;
            if after < mr * 0.4 && progress > 0.3 {
                score += 9.0 * (1.0 - after / (mr * 0.4)) * (0.5 + 0.7 * progress);
            }
        } else {
            score += 7.0 * (1.0 - fresh_post / n) * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 42): dead-space cubic ledger.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let dead_frac = 1.0 - pr / n;
        score += 5.0 * dead_frac * dead_frac * dead_frac * (n / cap_f).max(0.1) * (0.6 + 1.4 * stream_left);
    }

    // MUTATION (gen 42): late-stream exact-closure bias.
    if progress > 0.85 {
        let tail = (progress - 0.85) / 0.15;
        if post_residual == 0 {
            score -= 14.0 * tail;
        } else if post_residual <= 4 {
            score -= 10.0 * tail * (1.0 - post_residual as f64 / 5.0);
        } else {
            score += 8.0 * tail * ((post_residual as f64 / cap_f).min(0.3));
        }
    }

    // MUTATION (gen 42): residual ladder alignment.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round().max(1.0);
        let dev = (pr - k * mr).abs() / mr;
        if dev <= 0.12 && k <= 3.0 {
            score -= 8.0 * (1.0 - dev / 0.12) * (1.0 - 0.5 * progress) * (1.0 / k.sqrt());
        }
    }

    // MUTATION (gen 44): perfect-fit ladder — deepen the multiple-alignment reward
    // and extend it to the next item so chains close with zero waste.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 1.0 && (pr - k * n).abs() < 0.5 {
            score -= 12.0 * (1.0 + 0.9 * (1.0 - progress)) / k.sqrt();
        }
    }

    // MUTATION (gen 44): fresh-bin exact-closure gate — open a new bin only when
    // its post-residual is a clean multiple of the next item; otherwise penalize
    // proportionally to the stranded fraction, weighted by fitting alternatives.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let k = (fresh_post / n).round();
        if k < 1.0 || (fresh_post - k * n).abs() >= 2.0 {
            score += 10.0 * (1.0 - (fresh_post / (k.max(1.0) * n)).min(1.0))
                * (0.5 + 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0)
                * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 44): late-stream residual compression — squeeze the final
    // stretch by making small residuals dominate and large ones cost more.
    if progress > 0.8 && post_residual > 0 {
        let tail = (progress - 0.8) / 0.2;
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 6.0 * tail * (1.0 - pr / mr);
        } else {
            score += 5.0 * tail * ((pr - mr) / cap_f).min(0.2) * 10.0;
        }
    }

    // MUTATION (gen 44): two-step harvest lookahead — combine fine-grained residual
    // fitting with lookahead: prefer bins whose remainder after the next item sits
    // inside a tight harvest window around the mean residual, sharpened early.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after >= mr * 0.8 && after <= mr * 1.4 {
                let centering = 1.0 - ((after - mr) / (mr * 0.6)).abs();
                score -= 13.0 * centering * (0.5 + 0.7 * (1.0 - progress));
            }
        }
    }

    // MUTATION (gen 44): dead-space parity sharpening — penalize residuals just
    // below the next item more steeply as the stream depletes, converting the
    // diagnosed dead-space weakness into a hard veto.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 10.0 * (gap / n) * (0.6 + 1.3 * stream_left);
    }

    // MUTATION (gen 45): exact-fill competition tiebreak — when several bins fit,
    // sharpen preference for residuals that align on the mean-residual ladder.
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round();
        if k >= 1.0 && k <= 4.0 {
            let dev = (pr - k * mr).abs();
            if dev <= 1.5 {
                score -= 6.0 * (1.0 - dev / 1.5) * (0.5 + 0.8 * (1.0 - progress)) / k.sqrt();
            }
        }
    }

    // MUTATION (gen 45): pair-gap closure — bonus when item + next exactly (or
    // near-exactly) exhausts this bin's residual, borrowing from the best lineage.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 55.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 16.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 45): near-exact fill gap on open bins — reward bins where the
    // item leaves almost nothing, scaled by competition.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 20.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): dead-space entropy gate — residuals well below half the
    // next item are near-certain waste; penalize quadratically, late-weighted.
    if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let unusable = 1.0 - pr / (n * 0.5);
        score += 8.0 * unusable * unusable * (0.7 + 0.9 * (1.0 - progress));
    }

    // MUTATION (gen 45): fresh-bin pair-closure veto — a new bin is attractive when
    // the fresh post-residual exactly or nearly matches the next item; otherwise,
    // if the fresh residual is stranded below half the next item, penalize hard.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        if (fresh_post - n).abs() <= 0.5 && progress < 0.8 {
            score -= 16.0 * (1.0 - progress);
        } else if fresh_post < n * 0.5 && progress > 0.5 {
            score += 12.0 * (1.0 - fresh_post / (n * 0.5)) * (0.5 + 0.8 * progress);
        }
    }

    // MUTATION (gen 45): large-item consolidation — when a big item fits an open
    // bin, prefer it over opening a new bin to avoid stranded capacity.
    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 45): residual-deviation smoothing — reward residuals close to
    // the mean (predictable future fits) and penalize far outliers.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): two-item exact sum alignment — post-residual equal to
    // next + mean means the bin supports a clean two-step chain.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if (pr - (next_item_size as f64 + mr)).abs() <= 2.0 {
            score -= 15.0 * (1.0 - (pr - (next_item_size as f64 + mr)).abs() / 2.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 45): fresh-bin residual-quality gate — new bins whose residual
    // is off the mean-residual ladder are penalized; on-ladder ones rewarded early.
    if bin_residual == bin_capacity && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = fresh_post / mr;
        let frac = (k - k.round()).abs();
        if frac > 0.25 && progress > 0.25 {
            score += 11.0 * (frac - 0.25).min(0.5) * (0.6 + 0.6 * progress);
        } else if frac <= 0.1 && progress < 0.7 {
            score -= 7.0 * (1.0 - frac / 0.1) * (1.0 - progress);
        }
    }

    // MUTATION (gen 45): late-stream fresh-bin suppression — near the end, opening
    // a new bin almost always wastes capacity; push its score up steeply.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }

    // MUTATION (gen 45): harvest-depth ladder — reward multi-step chains where the
    // remainder after the next item stays harvestable by the mean residual.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let after = pr - n;
        let chain_k = (after / mr).floor();
        if chain_k >= 1.0 {
            let slack = after - chain_k * mr;
            let centered = 1.0 - (slack / mr).abs();
            score -= 11.0 * centered * (chain_k.min(3.0).sqrt()) * (0.7 + 0.9 * (1.0 - progress));
        }
    }

    // MUTATION (gen 45): mid-stream residual smoothing — between progress 0.35 and
    // 0.75, compress the score spread of mid-sized residuals so chain terms
    // dominate over raw magnitude, reducing premature fragmentation.
    if progress > 0.35 && progress < 0.75 && post_residual > 10 && post_residual < 40 {
        let mid = (progress - 0.35) / 0.4;
        let bell = (mid * (1.0 - mid) * 4.0).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr).abs() / mr;
        if dev <= 0.5 {
            score -= 6.0 * bell * (1.0 - dev / 0.5);
        } else {
            score += 4.0 * bell * (dev - 0.5).min(1.0);
        }
    }

    // MUTATION (gen 45): orphan sweep — late in the stream, residuals that can't
    // hold the next item become permanent waste; escalate their penalty.
    if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let tail = (progress - 0.75) / 0.25;
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        score += 14.0 * tail * (1.0 - pr / n) * (0.6 + 0.6 * tail);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // retained mutations.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
    }
    if post_residual >= 1 && post_residual <= 3 {
        score -= 12.0 * (4.0 - post_residual as f64) * (0.5 + progress);
    }
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 {
            score += 20.0 * (1.0 - fresh_post / next_item_size as f64) * (0.6 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        let follow = mean_residual.max(3.0).min(50.0);
        if after >= follow {
            score -= 10.0 * (1.0 - (after - follow) / cap_f) * (1.2 - 0.6 * progress);
        }
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mr = mean_residual.max(1.0);
        if (post_residual as f64) < mr * 0.5 && fitting_bins_count > 1 {
            score += 9.0 * (1.0 - post_residual as f64 / (mr * 0.5)) * (0.6 + 0.6 * progress);
        }
    }
    if post_residual >= 1 && post_residual <= 5 {
        score -= 8.0 * (6.0 - post_residual as f64) * (0.5 + progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let avg_fill = (cap_f - mean_residual).max(0.0);
        let this_fill = item_size as f64 / bin_residual as f64;
        let target = (avg_fill / cap_f).clamp(0.2, 0.95);
        if this_fill >= target {
            score -= 14.0 * (this_fill - target).min(0.4) * (0.8 + 0.6 * progress);
        } else {
            score += 7.0 * (target - this_fill) * (1.0 - 0.4 * progress);
        }
    }

    if post_residual > 0 {
        let mr = mean_residual.max(2.0);
        let pr = post_residual as f64;
        let k = pr / mr;
        if k >= 1.0 && (k - k.round()).abs() < 0.08 {
            score -= 10.0 * (1.0 - (k - k.round()).abs() / 0.08) * (1.1 - 0.5 * progress);
        }
    }

    if item_size as f64 >= cap_f * 0.5 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 16.0 * (bin_residual as f64 / cap_f) * (0.7 + 0.5 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev <= 4.0 {
            score -= 9.0 * (1.0 - dev / 4.0) * (0.6 + 0.5 * progress);
        } else if dev > 12.0 {
            score += 3.0 * ((dev - 12.0) / cap_f).min(0.15) * 10.0 * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 24 && post_residual < 45 && next_item_size > 0 && fitting_bins_count > 1 {
        let excess = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.55 * excess * (0.4 + 0.6 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if (pr - (n + mr)).abs() <= 2.0 {
            score -= 15.0 * (1.0 - (pr - (n + mr)).abs() / 2.0) * (1.0 - 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 1 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score += 12.0 * (1.0 - pr / mr) * (0.5 + 0.5 * progress);
        }
    }

    if fitting_bins_count <= 2 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let usable = next_item_size as f64 > 0.0 && pr >= next_item_size as f64;
        if !usable {
            let mr = mean_residual.max(2.0);
            let dead = pr.min(mr);
            score += 5.0 * (dead / mr).min(1.0) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual as f64 - next_item_size as f64;
        if after <= 10.0 {
            score -= 13.0 * (1.0 - after / 10.0) * (0.8 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 1 {
        let fresh_post = cap_f - item_size as f64;
        if fresh_post < next_item_size as f64 && fresh_post < mean_residual.max(2.0) {
            score += 24.0 * (1.0 - fresh_post / next_item_size as f64) * (1.0 - 0.3 * progress);
        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let fits_next = n > 0.0 && pr >= n;
        let fits_mean = pr >= mr;
        if !fits_next && !fits_mean {
            let waste = pr / cap_f;
            let stream_left = 1.0 - progress;
            score += (9.0 + 10.0 * stream_left) * (0.5 + waste).min(1.0);
        } else if !fits_next {
            score += 3.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let chain_gap = (after - mr).abs();
            if chain_gap <= 3.0 {
                score -= 11.0 * (1.0 - chain_gap / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    if post_residual >= 1 && post_residual <= 2 && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - post_residual as f64 / 3.0) * (0.8 + 0.4 * progress);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let fresh_post = cap_f - item_size as f64;
        let loose_elsewhere = mean_residual.max(2.0);
        if fresh_post < loose_elsewhere * 0.8 && progress > 0.3 {
            score -= 14.0 * (1.0 - fresh_post / (loose_elsewhere * 0.8)) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
        if d <= win {
            score -= 14.0 * (1.0 - d / win) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 18.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0).min(3.0);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(1.0);
        if fresh_post < mr {
            score += 16.0 * (1.0 - fresh_post / mr) * (0.6 + 0.6 * progress);
        } else if fresh_post > mr * 1.6 && progress < 0.6 {
            score -= 10.0 * ((fresh_post - mr * 1.6) / cap_f).min(0.2) * 10.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr < n && pr < mr {
            let stream_left = 1.0 - progress;
            score += 6.0 * (pr / mr) * (pr / mr) * (0.8 + 0.8 * stream_left);
        }
    }

    // gen 34 retained: competition-aware best-fit sharpening.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let comp = (fitting_bins_count as f64).max(1.0);
        let crowd = 1.0 / (1.0 + (comp.ln() * 0.6));
        score += pr * 0.12 * crowd * (0.6 + 0.6 * progress);
        if fitting_bins_count == 1 {
            score -= 9.0 * (1.0 - pr / cap_f) * (0.8 + 0.4 * progress);
        }
    }

    // gen 34 retained: two-step harvest lookahead.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after >= mr * 0.8 && after <= mr * 1.4 {
                score -= 13.0 * (1.0 - (after - mr).abs() / (mr * 0.6)) * (0.5 + 0.7 * (1.0 - progress));
            }
        }
    }

    // gen 34 retained: late-stream exact-closure bias.
    if progress > 0.85 {
        let tail = (progress - 0.85) / 0.15;
        if post_residual == 0 {
            score -= 14.0 * tail;
        } else if post_residual <= 4 {
            score -= 10.0 * tail * (1.0 - post_residual as f64 / 5.0);
        } else {
            score += 8.0 * tail * ((post_residual as f64 / cap_f).min(0.3));
        }
    }

    // gen 34 retained: fresh-bin residual-quality gate.
    if bin_residual == bin_capacity && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = fresh_post / mr;
        let frac = (k - k.round()).abs();
        if frac > 0.25 && progress > 0.25 {
            score += 11.0 * (frac - 0.25).min(0.5) * (0.6 + 0.6 * progress);
        } else if frac <= 0.1 && progress < 0.7 {
            score -= 7.0 * (1.0 - frac / 0.1) * (1.0 - progress);
        }
    }

    // gen 35 retained: dead-space parity sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 9.0 * (gap / n) * (0.6 + 1.2 * stream_left);
    }

    // gen 35 retained: harvest-chain density.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 4.0 {
                score -= 15.0 * (1.0 - d / 4.0) * (1.1 - 0.6 * progress);
            }
        }
    }

    // gen 35 retained: fresh-bin dead-space veto.
    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post < n {
            score += 18.0 * (1.0 - fresh_post / n) * (0.7 + 0.7 * progress);
        } else if (fresh_post - n).abs() <= 1.0 {
            score -= 20.0 * (1.0 - 0.5 * progress);
        } else if fresh_post > mr * 1.8 {
            score += 6.0 * ((fresh_post - mr * 1.8) / cap_f).min(0.25) * 8.0 * (0.4 + 0.6 * progress);
        }
    }

    // gen 35 retained: residual-variance-aware fit scaling.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let fragility = (mr / cap_f).clamp(0.02, 0.5);
        score += pr * fragility * 0.35 * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 40): chain-continuity refinement — when the post-residual
    // absorbs the next item and the remainder can still hold roughly the mean
    // residual, deepen the reward with a sharper centered window and a
    // competition-scaled bonus so multi-fitting bins win dead-space ties.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 3.0 {
                score -= 14.0 * (1.0 - d / 3.0) * (0.7 + 0.9 * (1.0 - progress));
                if fitting_bins_count > 1 {
                    score -= 4.0 * (1.0 - d / 3.0) * ((fitting_bins_count as f64).min(4.0) / 4.0);
                }
            }
        }
    }

    // MUTATION (gen 40): dead-space quadratic ledger — unusable residuals are
    // penalized quadratically in the shortfall, with weight rising as the stream
    // depletes, sharpening the diagnosed dead-space weakness beyond the linear
    // parity term.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let stranded = 1.0 - pr / n;
        score += 11.0 * stranded * stranded * (0.7 + 1.1 * stream_left);
    }

    // MUTATION (gen 40): fresh-bin harvest parity gate — a new bin is justified
    // only when its fresh post-residual is at least as harvestable as the mean
    // residual elsewhere; penalize short fresh residuals and reward ones that
    // land within a tight window of a multiple of the mean residual.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        if fresh_post < n {
            score += 14.0 * (1.0 - fresh_post / n) * (0.6 + 0.8 * progress);
        } else {
            let k = (fresh_post / mr).round().max(1.0);
            let dev = (fresh_post - k * mr).abs() / mr;
            if dev <= 0.1 && progress > 0.2 {
                score -= 9.0 * (1.0 - dev / 0.1) * (0.5 + 0.6 * (1.0 - progress)) / k.sqrt();
            } else if fresh_post > mr * 2.0 && progress > 0.5 {
                score += 7.0 * ((fresh_post - mr * 2.0) / cap_f).min(0.25) * 8.0 * (0.5 + 0.6 * progress);
            }
        }
    }

    // MUTATION (gen 40): late-stream exact-closure deepening — near the end of the
    // stream, residuals that exactly match the next item close a bin perfectly;
    // strengthen the reward quadratically in the tail fraction.
    if progress > 0.8 && post_residual > 0 && next_item_size > 0 {
        let tail = (progress - 0.8) / 0.2;
        if post_residual == next_item_size {
            score -= 18.0 * tail * tail;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 2 {
            score -= 10.0 * tail * (1.0 - (post_residual - next_item_size) as f64 / 3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let follow = mean_residual.max(4.0).min(40.0);
        if pr >= n + follow {
            score -= 16.0 * (1.0 - progress) * ((pr - n - follow) / cap_f).min(0.2).max(0.05) * 5.0;
        }
    }

    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // retained mutations.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0 * (0.4 + progress);
    }
    if post_residual > 0 && post_residual < 8 {
        score -= (8.0 - post_residual as f64) * 6.0 * (0.6 + progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = pr / n;
        if (k - k.floor()).abs() < 0.05 && k >= 2.0 && k <= 3.5 {
            score -= 12.0 * (1.0 - progress);
        }
    }
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 45.0 * (progress - 0.85) / 0.15;
    }
    if post_residual > 8 && post_residual < 25 {
        let g = (post_residual as f64 - 8.0) / 17.0;
        score += 36.0 * g * (1.0 - g) * (0.7 + progress);
    }
    if post_residual == 0 && next_item_size > 0 && (mean_residual - next_item_size as f64).abs() <= 1.5 {
        score -= 35.0 * (0.5 + progress);
