                score += 4.0 * (1.0 - after / (mr * 0.5)) * (0.4 + 0.8 * stream_left);
            }
        }
    }

    // gen 48 retained: fresh-bin parity lock.
    if bin_residual == bin_capacity && post_residual > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = (fresh_post / mr).max(0.0);
        let frac = k - k.floor();
        let misalign = if frac <= 0.5 { frac } else { 1.0 - frac };
        if misalign > 0.2 {
            score += 9.0 * (misalign - 0.2) / 0.3 * (0.5 + 0.7 * (1.0 - progress));
        } else if misalign < 0.05 {
            score -= 6.0 * (1.0 - misalign / 0.05) * (0.6 + 0.6 * progress);
        }
    }

    // MUTATION (gen 49): waste-budget fresh-bin veto — when a new bin is a
    // candidate, penalize it proportionally to the fraction of its leftover
    // that cannot be covered by the next item plus one mean-residual unit,
    // scaled by how much of the stream remains; this directly targets the
    // 53-bin dead-space gap by refusing fresh bins whose post-fill leftover
    // is likely to strand capacity.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let cover = n + mr;
        let uncovered = (fresh_post - cover).max(0.0) / cap_f;
        let stream_left = 1.0 - progress;
        score += 14.0 * uncovered * (0.4 + 1.2 * stream_left);
        if fresh_post >= cover && (fresh_post - cover) <= mr * 0.3 {
            score -= 10.0 * (1.0 - (fresh_post - cover) / (mr * 0.3)) * (0.5 + 0.7 * progress);
        }
    }

    // MUTATION (gen 49): two-step exact-closure ladder — reward placements
    // where post_residual exactly equals next_item_size, or equals it plus a
    // small sliver that itself closes on a mean-residual multiple; this
    // synthesizes fine-grained best-fit with the lookahead chain, sharpening
    // the harvest of near-terminal residuals.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let d = (pr - n).abs();
        if d <= 1.0 {
            score -= 12.0 * (1.0 - d) * (0.6 + 0.8 * (1.0 - progress));
        } else if pr > n && (pr - n) <= mr * 0.25 {
            let after = pr - n;
            let k = (after / mr).round().max(1.0);
            if (after - k * mr).abs() <= 1.0 {
                score -= 7.0 * (1.0 - (after - k * mr).abs()) * (0.5 + 0.6 * progress);
            }
        }
    }

    // MUTATION (gen 49): late-stream competition consolidation — in the final
    // quarter, when several bins can host the item, prefer the one whose
    // post-residual is smallest (strongest closure pressure) with a bonus
    // that grows with the number of competitors, collapsing fragmented
    // tails into fewer bins.
    if progress > 0.75 && post_residual > 0 && fitting_bins_count > 1 && bin_residual != bin_capacity {
        let tail = (progress - 0.75) / 0.25;
        let comp = (fitting_bins_count as f64 - 1.0).min(4.0);
        let pr = post_residual as f64;
        score -= 6.0 * tail * comp * (1.0 - pr / cap_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Two-item harmony: item + next exactly fills the bin is the ideal outcome.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        // Fresh-bin pair-fit chain — open a fresh bin when the
        // item + next pair fits cleanly, giving the next item an exact fit.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Reward using residual that would otherwise be dead space.
    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    // Penalize leaving medium-sized dead space with a sharper gradient.
    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    // Fragmentation index.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Tightness reward: non-linear preference for small post-residuals.
    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    // Pair-fit anticipation: next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    // Best-fit cascade under scarcity: preserve empty capacity for large items.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    // Fine-grained dead-gap gradient — smooth surcharge growing as
    // the gap shrinks toward zero, so tiny slivers are punished hardest.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    // Dead-space forecast — residual is only valuable if future
    // items can actually use it.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        // Sweet-spot reward: residuals 8..=24 absorb typical small items well.
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        // Two-step lookahead: bias toward gaps that serve the immediate future.
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    // Extended near-full band — 5-10% residuals mildly rewarded,
    // weighted late, to squeeze remaining dead space.
    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    // Combined residual-fit + lookahead synergy.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    // Capacity-halving conservation.
    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Dead-space divisibility test.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    // Scarcity-aware tightness boost.
    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    // Residual quantization reward.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr > n {
            let k = (pr / n).floor();
            let rem = pr - k * n;
            if rem < 3.0 && k >= 1.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress);
            }
            if (pr - k * n) < 1.0 {
                score += 5.0 * progress;
            }
        }
    }

    // Dual-size chain check.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let chain = next_item_size as f64 + mean_residual.max(1.0);
        if pr >= chain {
            score -= 9.0 * (1.0 - (pr - chain) / cap_f).min(1.0) * (0.6 + progress);
        }
    }

    // New-bin suppression under consolidation.
    if bin_residual == bin_capacity && open_bins_count > 2 && fitting_bins_count > 1 {
        score += 12.0 * (open_bins_count as f64).ln() * (1.0 - progress);
        if next_item_size as f64 > cap_f * 0.5 {
            score -= 20.0;
        }
    }

    // Tight-fit precision band — an item that nearly exactly fills the
    // bin's residual (gap <= 3) is a near-perfect compaction event.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }

    // Perfect-pair lookahead — when item + next exactly matches the
    // residual, escalate the reward late in the stream; add a soft band
    // for near-exact pairs (within 2) to guide chain packing.
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // Fresh-bin waste guard — a new bin should only win when the leftover
    // capacity of the fresh bin would be genuinely usable.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    // Residual utility ratio — residuals far below the mean open-bin
    // residual are likely unusable dead space.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        if pr < mr * 0.5 {
            score += 10.0 * (1.0 - pr / (mr * 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Late-stream consolidation gate — opening a new bin is almost never
    // worthwhile when any open bin fits; raise the fresh-bin barrier
    // progressively.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= cap_f * 0.5 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 48): exact-closure escalation — a placement that leaves
    // the next item an exact fit is worth more when few bins compete for it
    // and the stream is winding down; sharpen the tiebreak so the best-fit
    // candidate wins deterministically over looser bins.
    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        let comp = (fitting_bins_count as f64).ln().max(1.0).min(3.0);
        score -= 14.0 * comp * (0.5 + 0.7 * (1.0 - progress));
    }

    // MUTATION (gen 48): dead-sliver quadratic veto — residuals that cannot
    // hold the next item OR the mean demand are stranded capacity; penalize
    // quadratically in the stranded fraction, weighted by remaining stream
    // volume so early waste is punished hardest.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let stream_left = 1.0 - progress;
        if pr < n && pr < mr {
            let stranded = 1.0 - pr / n.max(mr);
            score += 12.0 * stranded * stranded * (0.7 + 1.2 * stream_left);
        }
    }

    // MUTATION (gen 48): fresh-bin chain-floor gate — a new bin is justified
    // only if its leftover after the next item still covers at least half a
    // mean demand unit; otherwise penalize with strength growing as fewer
    // fitting alternatives exist and the stream dries up.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let after = fresh_post - n;
        if after < mr * 0.5 {
            let deficit = 1.0 - (after / (mr * 0.5)).max(0.0);
            let scarcity = ((4.0 - fitting_bins_count as f64).max(1.0)) / 4.0;
            score += 11.0 * deficit * scarcity * (0.5 + 0.9 * (1.0 - progress));
        } else if after >= mr * 1.4 && progress < 0.5 {
            score -= 6.0 * ((after - mr * 1.4) / cap_f).min(0.2) * 5.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 48): harvest-multiple alignment — when the post-residual
    // is a near-exact integer multiple of the next item size, the bin can be
    // closed out by a run of identical future items; reward with a soft
    // reciprocal-depth factor, strongest mid-stream where runs are likely.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 2.0 && k <= 4.0 {
            let dev = (pr - k * n).abs() / n;
            if dev <= 0.06 {
                let mid = 1.0 - (2.0 * progress - 1.0).abs();
                score -= 8.0 * (1.0 - dev / 0.06) * (0.4 + 0.8 * mid) / k.sqrt();
            }
        }
    }

    // MUTATION (gen 48): late-tail sliver sweep — in the final stretch every
    // unused unit of residual is a lost compaction; escalate the reward for
    // near-zero residuals and penalize any residual above a quarter-capacity
    // bin, scaled by tail intensity.
    if progress > 0.8 {
        let tail = (progress - 0.8) / 0.2;
        if post_residual > 0 && post_residual <= 5 {
            score -= 9.0 * tail * (6.0 - post_residual as f64);
        } else if post_residual as f64 > cap_f * 0.25 && bin_residual != bin_capacity {
            score += 7.0 * tail * ((post_residual as f64 / cap_f).min(0.5));
        }
    }

    score
}

