        score += 4.0 * (1.0 - (post_residual as f64 - 4.0) / 5.0) * (0.4 + 0.6 * progress);
    }

    // gen 47 retained: liquidity band refinement.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.4 {
            let dead = (0.4 - liquidity) / 0.4;
            score += 6.0 * dead * dead * (0.6 + 1.4 * stream_left);
        } else if liquidity <= 2.0 {
            let center = (1.0 - (liquidity - 1.0).abs() / 1.0).max(0.0);
            score -= 7.0 * center * (0.5 + 0.7 * stream_left);
        }
    }

    // gen 47 retained: harvest-continuity guard.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = (after / mr).round().max(1.0);
        let dev = (after - k * mr).abs() / mr;
        if dev <= 0.15 {
            score -= 6.0 * (1.0 - dev / 0.15) * (0.4 + 0.9 * progress) / k.sqrt();
        }
    }

    // gen 47 retained: fresh-bin chain-depth discount.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let slack_after_next = fresh_post - n;
        if slack_after_next < mr * 0.5 {
            let deficit = 1.0 - (slack_after_next / (mr * 0.5)).max(0.0);
            score += 8.0 * deficit * (0.5 + 1.0 * stream_left);
        } else if slack_after_next >= mr * 1.5 && stream_left > 0.2 {
            score -= 5.0 * ((slack_after_next - mr * 1.5) / cap_f).min(0.2) * 5.0 * stream_left;
        }
    }

    // MUTATION (gen 48): liquidity-band gradient sharpening — replace the flat
    // triangular reward with a peaked quadratic kernel centered at liquidity 1.0
    // so bins whose post-residual matches exactly one mean-demand unit win
    // decisively, while the dead-zone edge is pushed to 0.45 with a steeper
    // cubic ramp; also scale the reward band width by remaining stream volume
    // so mid-stream placements tolerate slightly wider residuals.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.45 {
            let dead = (0.45 - liquidity) / 0.45;
            score += 7.5 * dead * dead * dead * (0.6 + 1.4 * stream_left);
        } else if liquidity <= 2.2 {
            let center = (1.0 - (liquidity - 1.0).abs() / 1.2).max(0.0);
            score -= 8.5 * center * center * (0.5 + 0.7 * stream_left);
        }
    }

    // MUTATION (gen 48): two-step chain closure — when post-residual exactly
    // equals next item plus mean residual (a full chain link), reward strongly;
    // this targets the measured dead-space weakness by preferring placements
    // whose leftovers align with the observed demand rhythm.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64 + mean_residual.max(2.0);
        let dev = (pr - target).abs();
        if dev <= 2.0 {
            score -= 16.0 * (1.0 - dev / 2.0) * (0.6 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION (gen 48): fresh-bin half-fill veto refinement — penalize opening
    // a new bin when its post-residual falls into the "awkward middle" band
    // (between 0.35 and 0.65 of capacity) that historically wastes space,
    // while still rewarding fresh bins whose leftover exceeds 0.7 capacity.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_frac = (cap_f - item_size as f64) / cap_f;
        if fresh_frac > 0.35 && fresh_frac < 0.65 {
            let mid = 1.0 - ((fresh_frac - 0.5).abs() / 0.15).min(1.0);
            score += 9.0 * mid * (0.4 + 0.8 * (1.0 - progress));
        } else if fresh_frac >= 0.7 {
            score -= 6.0 * ((fresh_frac - 0.7) / 0.3).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (fitting_bins_count.min(5) as f64 / 5.0);
    }

    if bin_residual == bin_capacity {
        let small_early = item_size <= bin_capacity / 4 && progress < 0.5;
        if small_early {
            score += 30.0;
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && post_residual < 6 {
        score += 90.0 * (1.0 - post_residual as f64 / 6.0) * (0.7 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
        if d <= win {
            score -= 14.0 * (1.0 - d / win) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 18.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0).min(3.0);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(1.0);
        if fresh_post < mr {
            score += 16.0 * (1.0 - fresh_post / mr) * (0.6 + 0.6 * progress);
        } else if fresh_post > mr * 1.6 && progress < 0.6 {
            score -= 10.0 * ((fresh_post - mr * 1.6) / cap_f).min(0.2) * 10.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr < n && pr < mr {
            let stream_left = 1.0 - progress;
            score += 6.0 * (pr / mr) * (pr / mr) * (0.8 + 0.8 * stream_left);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let chain_gap = (after - mr).abs();
            if chain_gap <= 3.0 {
                score -= 12.0 * (1.0 - chain_gap / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let fits_next = n > 0.0 && pr >= n;
        let fits_mean = pr >= mr;
        if !fits_next && !fits_mean {
            let waste = pr / cap_f;
            let stream_left = 1.0 - progress;
            score += (9.0 + 10.0 * stream_left) * (0.5 + waste).min(1.0);
        } else if !fits_next {
            score += 3.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual >= 1 && post_residual <= 2 && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - post_residual as f64 / 3.0) * (0.8 + 0.4 * progress);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let fresh_post = cap_f - item_size as f64;
        let loose_elsewhere = mean_residual.max(2.0);
        if fresh_post < loose_elsewhere * 0.8 && progress > 0.3 {
            score -= 14.0 * (1.0 - fresh_post / (loose_elsewhere * 0.8)) * (0.5 + 0.5 * progress);
        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let stream_left = 1.0 - progress;
        score -= 18.0 * (0.5 + 1.0 * stream_left);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 1.5 {
                score -= 10.0 * (1.0 - d / 1.5) * (0.6 + 0.9 * (1.0 - progress));
            }
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post >= n {
            let after = fresh_post - n;
            if after < mr * 0.4 && progress > 0.3 {
                score += 9.0 * (1.0 - after / (mr * 0.4)) * (0.5 + 0.7 * progress);
            }
        } else {
            score += 7.0 * (1.0 - fresh_post / n) * (0.6 + 0.6 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let dead_frac = 1.0 - pr / n;
        score += 5.0 * dead_frac * dead_frac * dead_frac * (n / cap_f).max(0.1) * (0.6 + 1.4 * stream_left);
    }

    if progress > 0.85 {
        let tail = (progress - 0.85) / 0.15;
        if post_residual == 0 {
            score -= 14.0 * tail;
        } else if post_residual <= 4 {
            score -= 10.0 * tail * (1.0 - post_residual as f64 / 5.0);
        } else {
            score += 8.0 * tail * ((post_residual as f64 / cap_f).min(0.3));
        }
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round().max(1.0);
        let dev = (pr - k * mr).abs() / mr;
        if dev <= 0.12 && k <= 3.0 {
            score -= 8.0 * (1.0 - dev / 0.12) * (1.0 - 0.5 * progress) * (1.0 / k.sqrt());
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 1.0 && (pr - k * n).abs() < 0.5 {
            score -= 12.0 * (1.0 + 0.9 * (1.0 - progress)) / k.sqrt();
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let k = (fresh_post / n).round();
        if k < 1.0 || (fresh_post - k * n).abs() >= 2.0 {
            score += 10.0 * (1.0 - (fresh_post / (k.max(1.0) * n)).min(1.0))
                * (0.5 + 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0)
                * (0.6 + 0.6 * progress);
        }
    }

    if progress > 0.8 && post_residual > 0 {
        let tail = (progress - 0.8) / 0.2;
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 6.0 * tail * (1.0 - pr / mr);
        } else {
            score += 5.0 * tail * ((pr - mr) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after >= mr * 0.8 && after <= mr * 1.4 {
                let centering = 1.0 - ((after - mr) / (mr * 0.6)).abs();
                score -= 13.0 * centering * (0.5 + 0.7 * (1.0 - progress));
            }
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 10.0 * (gap / n) * (0.6 + 1.3 * stream_left);
    }

    // MUTATION (gen 48): residual-liquidity refinement — replace the flat dead-zone
    // ramp with a smooth quadratic penalty below 0.4 liquidity and a triangular
    // reward band centered at one mean-demand unit, so bins whose remainder covers
    // roughly the average future need beat both near-dead and over-large leftovers.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.4 {
            let dead = (0.4 - liquidity) / 0.4;
            score += 6.0 * dead * dead * (0.6 + 1.4 * stream_left);
        } else if liquidity <= 2.0 {
            let center = (1.0 - (liquidity - 1.0).abs() / 1.0).max(0.0);
            score -= 7.0 * center * (0.5 + 0.7 * stream_left);
        }
    }

    // MUTATION (gen 48): harvest-continuity guard — when the post-residual can hold
    // the next item, reward placements whose leftover after that item stays aligned
    // with the mean residual, keeping chains alive; weight grows late in the stream.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = (after / mr).round().max(1.0);
        let dev = (after - k * mr).abs() / mr;
        if dev <= 0.15 {
            score -= 6.0 * (1.0 - dev / 0.15) * (0.4 + 0.9 * progress) / k.sqrt();
        }
    }

    // MUTATION (gen 48): fresh-bin chain-depth discount — a new bin must support at
    // least the next item plus half a mean unit of slack; otherwise penalize with
    // strength rising as the stream dries up, since late fresh bins waste the most.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let slack_after_next = fresh_post - n;
        if slack_after_next < mr * 0.5 {
            let deficit = 1.0 - (slack_after_next / (mr * 0.5)).max(0.0);
            score += 8.0 * deficit * (0.5 + 1.0 * stream_left);
        } else if slack_after_next >= mr * 1.5 && stream_left > 0.2 {
            score -= 5.0 * ((slack_after_next - mr * 1.5) / cap_f).min(0.2) * 5.0 * stream_left;
        }
    }

    // MUTATION (gen 48): exact-closure competition bonus — when the item closes a
    // bin perfectly and multiple bins compete for it, deepen the reward so the
    // tightest closure always wins, reducing stranded near-full bins.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 6.0 * ((fitting_bins_count as f64).ln() + 1.0).min(3.0) * (0.5 + 0.7 * (1.0 - progress));
    }

    // MUTATION (gen 48): pair-window lookahead — when the item plus the next item
    // nearly exhausts the bin (within a couple of units), reward it as a chain
    // closure, with strength scaled by remaining stream and fitting competition.
    if next_item_size > 0 && bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap >= next_item_size && gap - next_item_size <= 2 {
            let near = 1.0 - (gap - next_item_size) as f64 / 3.0;
            score -= 9.0 * near * (0.5 + 0.8 * (1.0 - progress)) * (1.0 / (fitting_bins_count.max(1) as f64).sqrt());
        }
    }

    // MUTATION (gen 48): mid-stream liquidity smoothing — in the middle of the
    // stream, gently prefer residuals within half a mean unit of the mean demand
    // and penalize outliers, reducing residual variance and dead space.
    if progress > 0.35 && progress < 0.75 && post_residual > 10 && post_residual < 40 {
        let mid = (progress - 0.35) / 0.4;
        let bell = (mid * (1.0 - mid) * 4.0).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let dev = (pr - mr).abs() / mr;
        if dev <= 0.5 {
            score -= 6.0 * bell * (1.0 - dev / 0.5);
        } else {
            score += 4.0 * bell * (dev - 0.5).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 8 {
        score -= 70.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 60.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / cap_f);
        } else {
            score += 12.0 + 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 200.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += (mean_residual - bin_residual as f64) * 0.5;

    if bin_residual == bin_capacity {
        score += 140.0 * progress + 25.0;
        if post_residual == 0 {
            score -= 450.0;
        }
        if progress < 0.2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual != 0 && post_residual < next_item_size {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual - item_size < next_item_size && bin_residual - item_size > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 22.0 * (1.0 - progress);
        }
    }

    if item_size > bin_capacity / 2 {
        score -= 25.0;
        if post_residual < bin_capacity / 8 {
            score -= 15.0;
        }
    }

    if post_residual > 25 && post_residual < 60 {
        score += 10.0 + 0.2 * (post_residual as f64 - 25.0);
    }

    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual).min(30.0);
    }

    let tightness = (post_residual as f64 / cap_f).powi(4);
    score += tightness * 60.0;

    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 120.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 18.0 * (1.0 - bin_residual as f64 / cap_f);
    }

    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.9 * (0.6 + progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand_proxy = mean_residual.max(next_item_size as f64).max(1.0);
        let usability = pr / demand_proxy;
        if usability < 0.35 {
            score += 14.0 * (0.35 - usability) * (1.0 + progress);
        } else if usability < 0.6 {
            score += 4.0 * (0.6 - usability);
        }
        if post_residual >= 8 && post_residual <= 24 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= 2.0 * next_item_size as f64 {
            score -= 9.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 {
        let frac = post_residual as f64 / cap_f;
        if frac < 0.05 {
            score -= 20.0 * (0.05 - frac) * 20.0 * (0.5 + progress);
        } else if frac < 0.10 {
            score -= 12.0 * (0.10 - frac) * 20.0 * (0.4 + progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 6.0 {
            score -= 18.0 * (1.0 - (pr - n) / 6.0) * (0.7 + progress);
        }
        if pr < n && fitting_bins_count > 1 {
            score += 8.0 * (1.0 - pr / n) * (0.5 + 0.5 * progress);
        }
    }

    if item_size as f64 <= cap_f * 0.4 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score += 10.0 * (1.0 - bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let demand = if next_item_size > 0 { next_item_size as f64 } else { mean_residual.max(1.0) };
        if pr < demand * 0.5 {
            score += 26.0 * (1.0 - pr / (demand * 0.5)) * (0.8 + progress);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let after = pr - next_item_size as f64;
            if after >= 8.0 {
                score -= 7.0 * (after / cap_f).min(0.25) * 4.0 * (0.6 + progress);
            }
        }
    }

    if fitting_bins_count <= 3 && bin_residual != bin_capacity {
        score += 6.0 * (bin_residual as f64 / cap_f) * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (fitting_bins_count.min(5) as f64 / 5.0);
    }

    if bin_residual == bin_capacity {
        let small_early = item_size <= bin_capacity / 4 && progress < 0.5;
        if small_early {
            score += 30.0;
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && post_residual < 6 {
        score += 90.0 * (1.0 - post_residual as f64 / 6.0) * (0.7 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let near_miss = 1.0 - pr / n;
        let stream_left = 1.0 - progress;
        score += 22.0 * near_miss * (0.6 + 0.8 * stream_left);
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(1.0);
        let win = 2.0 + 2.0 * (1.0 - progress);
        let d = (pr - mr).abs();
        if d <= win {
            score -= 14.0 * (1.0 - d / win) * (0.7 + 0.5 * progress);
        }
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 18.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0).min(3.0);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(1.0);
        if fresh_post < mr {
            score += 16.0 * (1.0 - fresh_post / mr) * (0.6 + 0.6 * progress);
        } else if fresh_post > mr * 1.6 && progress < 0.6 {
            score -= 10.0 * ((fresh_post - mr * 1.6) / cap_f).min(0.2) * 10.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr < n && pr < mr {
            let stream_left = 1.0 - progress;
            score += 6.0 * (pr / mr) * (pr / mr) * (0.8 + 0.8 * stream_left);
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let chain_gap = (after - mr).abs();
            if chain_gap <= 3.0 {
                score -= 12.0 * (1.0 - chain_gap / 3.0) * (0.7 + 0.5 * progress);
            }
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let fits_next = n > 0.0 && pr >= n;
        let fits_mean = pr >= mr;
        if !fits_next && !fits_mean {
            let waste = pr / cap_f;
            let stream_left = 1.0 - progress;
            score += (9.0 + 10.0 * stream_left) * (0.5 + waste).min(1.0);
        } else if !fits_next {
            score += 3.0 * (1.0 - 0.5 * progress);
        }
    }

    if post_residual >= 1 && post_residual <= 2 && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - post_residual as f64 / 3.0) * (0.8 + 0.4 * progress);
    }

    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        let fresh_post = cap_f - item_size as f64;
        let loose_elsewhere = mean_residual.max(2.0);
        if fresh_post < loose_elsewhere * 0.8 && progress > 0.3 {
            score -= 14.0 * (1.0 - fresh_post / (loose_elsewhere * 0.8)) * (0.5 + 0.5 * progress);
        }
    }

    if progress > 0.7 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let late = (progress - 0.7) / 0.3;
        if pr <= 12.0 {
            score -= 16.0 * late * (1.0 - pr / 12.0);
        } else if pr >= 30.0 {
            score += 8.0 * late * ((pr - 30.0) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        let stream_left = 1.0 - progress;
        score -= 18.0 * (0.5 + 1.0 * stream_left);
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            let d = (after - mr).abs();
            if d <= 1.5 {
                score -= 10.0 * (1.0 - d / 1.5) * (0.6 + 0.9 * (1.0 - progress));
            }
        }
    }

    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if fresh_post >= n {
            let after = fresh_post - n;
            if after < mr * 0.4 && progress > 0.3 {
                score += 9.0 * (1.0 - after / (mr * 0.4)) * (0.5 + 0.7 * progress);
            }
        } else {
            score += 7.0 * (1.0 - fresh_post / n) * (0.6 + 0.6 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let stream_left = 1.0 - progress;
        let dead_frac = 1.0 - pr / n;
        score += 5.0 * dead_frac * dead_frac * dead_frac * (n / cap_f).max(0.1) * (0.6 + 1.4 * stream_left);
    }

    if progress > 0.85 {
        let tail = (progress - 0.85) / 0.15;
        if post_residual == 0 {
            score -= 14.0 * tail;
        } else if post_residual <= 4 {
            score -= 10.0 * tail * (1.0 - post_residual as f64 / 5.0);
        } else {
            score += 8.0 * tail * ((post_residual as f64 / cap_f).min(0.3));
        }
    }

    if post_residual > 0 {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let k = (pr / mr).round().max(1.0);
        let dev = (pr - k * mr).abs() / mr;
        if dev <= 0.12 && k <= 3.0 {
            score -= 8.0 * (1.0 - dev / 0.12) * (1.0 - 0.5 * progress) * (1.0 / k.sqrt());
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let k = (pr / n).round();
        if k >= 1.0 && (pr - k * n).abs() < 0.5 {
            score -= 12.0 * (1.0 + 0.9 * (1.0 - progress)) / k.sqrt();
        }
    }

    if bin_residual == bin_capacity && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let n = next_item_size as f64;
        let k = (fresh_post / n).round();
        if k < 1.0 || (fresh_post - k * n).abs() >= 2.0 {
            score += 10.0 * (1.0 - (fresh_post / (k.max(1.0) * n)).min(1.0))
                * (0.5 + 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0)
                * (0.6 + 0.6 * progress);
        }
    }

    if progress > 0.8 && post_residual > 0 {
        let tail = (progress - 0.8) / 0.2;
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        if pr < mr {
            score -= 6.0 * tail * (1.0 - pr / mr);
        } else {
            score += 5.0 * tail * ((pr - mr) / cap_f).min(0.2) * 10.0;
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let mr = mean_residual.max(2.0);
        if pr >= n {
            let after = pr - n;
            if after >= mr * 0.8 && after <= mr * 1.4 {
                let centering = 1.0 - ((after - mr) / (mr * 0.6)).abs();
                score -= 13.0 * centering * (0.5 + 0.7 * (1.0 - progress));
            }
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        let gap = n - pr;
        let stream_left = 1.0 - progress;
        score += 10.0 * (gap / n) * (0.6 + 1.3 * stream_left);
    }

    // MUTATION (gen 48): residual-liquidity refinement — replace the flat dead-zone
    // ramp with a smooth quadratic penalty below 0.4 liquidity and a triangular
    // reward band centered at one mean-demand unit, so bins whose remainder covers
    // roughly the average future need beat both near-dead and over-large leftovers.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let liquidity = pr / mr;
        if liquidity < 0.4 {
            let dead = (0.4 - liquidity) / 0.4;
            score += 6.0 * dead * dead * (0.6 + 1.4 * stream_left);
        } else if liquidity <= 2.0 {
            let center = (1.0 - (liquidity - 1.0).abs() / 1.0).max(0.0);
            score -= 7.0 * center * (0.5 + 0.7 * stream_left);
        }
    }

    // MUTATION (gen 48): harvest-continuity guard — when the post-residual can hold
    // the next item, reward placements whose leftover after that item stays aligned
    // with the mean residual, keeping chains alive; weight grows late in the stream.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = post_residual as f64 - next_item_size as f64;
        let mr = mean_residual.max(2.0);
        let k = (after / mr).round().max(1.0);
        let dev = (after - k * mr).abs() / mr;
        if dev <= 0.15 {
            score -= 6.0 * (1.0 - dev / 0.15) * (0.4 + 0.9 * progress) / k.sqrt();
        }
    }

    // MUTATION (gen 48): fresh-bin chain-depth discount — a new bin must support at
    // least the next item plus half a mean unit of slack; otherwise penalize with
    // strength rising as the stream dries up, since late fresh bins waste the most.
    if bin_residual == bin_capacity && post_residual > 0 && fitting_bins_count > 0 {
        let fresh_post = cap_f - item_size as f64;
        let mr = mean_residual.max(2.0);
        let stream_left = 1.0 - progress;
        let n = if next_item_size > 0 { next_item_size as f64 } else { mr };
        let slack_after_next = fresh_post - n;
        if slack_after_next < mr * 0.5 {
            let deficit = 1.0 - (slack_after_next / (mr * 0.5)).max(0.0);
            score += 8.0 * deficit * (0.5 + 1.0 * stream_left);
        } else if slack_after_next >= mr * 1.5 && stream_left > 0.2 {
            score -= 5.0 * ((slack_after_next - mr * 1.5) / cap_f).min(0.2) * 5.0 * stream_left;
        }
    }

    // MUTATION (gen 48): exact-closure competition bonus — when the item closes a
    // bin perfectly and multiple bins compete for it, deepen the reward so the
    // tightest closure always wins, reducing stranded near-full bins.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count > 1 {
        score -= 6.0 * ((fitting_bins_count as f64).ln() + 1.0).min(3.0) * (0.5 + 0.7 * (1.0 - progress));
    }

    // MUTATION (gen 48): pair-window lookahead — when the item plus the next item
    // nearly exhausts the bin (within a couple of units), reward it as a chain
    // closure, with strength scaled by remaining stream and fitting competition.
    if next_item_size > 0 && bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap >= next_item_size && gap - next_item_size <= 2 {
            let near = 1.0 - (gap - next_item_size) as f64 / 3.0;
            score -= 9.0 * near * (0.5 + 0.8 * (1.0 - progress)) * (1.0 / (fitting_bins_count.max(1) as f64).sqrt());
        }
    }

    // MUTATION (gen 48): micro-gap closure sharpening — strongly reward placements
    // leaving a gap of at most 3 units, since tiny leftovers are near-zero waste;
    // combine with a next-item pair alignment term that rewards residuals whose
    // remaining space after this item matches the upcoming item exactly or within
    // 2 units, merging fine-grained fitting with lookahead anticipation.
    if bin_residual != bin_capacity && bin_residual >= item_size {
        let gap = bin_residual - item_size;
        if gap <= 3 {
            score -= 22.0 * (4.0 - gap as f64) * (0.7 + 0.5 * progress);
        }
    }
    if next_item_size > 0 && bin_residual >= item_size {
        let pair_gap = (bin_residual - item_size).abs_diff(next_item_size);
        if pair_gap == 0 {
            score -= 60.0 * (0.5 + progress);
        } else if pair_gap <= 2 {
            score -= 18.0 * (1.0 - pair_gap as f64 / 3.0) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 48): fresh-bin future-fit bonus — when the leftover of a new
    // bin comfortably holds the next item, discount the fresh-bin penalty in
    // proportion to how much usable space remains, encouraging early opening of
    // bins that will chain multiple items instead of fragmenting existing ones.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= next_item_size {
            score += 14.0 * (fresh_post as f64 / cap_f) * (0.5 + progress);
        }
    }

    score
}

